const S=[{id:"o201",n:201,t:0,origin:"original",eco:"P1",domain:"people",approach:"hybrid",tags:["vision","alignment"],type:"mc",q:"A hybrid product initiative has three department leads who describe success differently. Delivery has not started. What should the project manager do first?",opts:["Facilitate a session to create and validate one shared vision","Ask the sponsor to select the most important department","Create separate success criteria for each department","Start the highest-value work and resolve alignment later"],ans:[0],why:["Đúng: tạo hiểu biết chung trước khi thực thi.","Sponsor không nên thay thế đối thoại khi các bên có thể cùng căn chỉnh.","Ba định nghĩa thành công tiếp tục kéo dự án theo ba hướng.","Khởi công khi chưa thống nhất làm tăng rework."],exp:"P1 kiểm tra khả năng tạo **shared vision**. Trước khi chọn giải pháp hoặc ưu tiên, PM cần làm rõ giá trị chung và xác nhận các bên cùng hiểu."},{id:"o202",n:202,t:0,origin:"original",eco:"P2",domain:"people",approach:"agile",tags:["conflict","ground-rules"],type:"mc",q:"Two senior developers repeatedly interrupt each other during refinement and the rest of the team has stopped contributing. What should the project manager do next?",opts:["Replace both developers on the team","Meet with the parties, understand the source, and reinforce agreed ground rules","Cancel refinement until the conflict disappears","Escalate immediately to their functional managers"],ans:[1],why:["Quá sớm và làm mất tri thức.","Đúng: hiểu nguồn xung đột rồi dùng ground rules đã thống nhất.","Trì hoãn không giải quyết nguyên nhân.","Escalation chỉ phù hợp khi đội không thể giải quyết trong thẩm quyền."],exp:"Ưu tiên giải quyết trực tiếp, hợp tác và bảo vệ psychological safety. Escalate không phải bước mặc định đầu tiên."},{id:"o203",n:203,t:0,origin:"original",eco:"P3",domain:"people",approach:"agile",tags:["leadership","empowerment"],type:"mc",q:"A mature agile team asks the project manager to approve every technical decision, creating a bottleneck. What is the best response?",opts:["Continue approvals to maintain accountability","Delegate all project governance decisions to the team","Clarify decision boundaries and empower the team inside those boundaries","Assign one architect to make every technical decision"],ans:[2],why:["Duy trì bottleneck.","Governance vẫn cần đúng thẩm quyền.","Đúng: trao quyền đi cùng ranh giới rõ ràng.","Chuyển bottleneck sang một cá nhân khác."],exp:"Servant leadership không bỏ trách nhiệm; PM thiết kế ranh giới để đội tự quyết ở mức phù hợp."},{id:"o204",n:204,t:0,origin:"original",eco:"P4",domain:"people",approach:"predictive",tags:["stakeholder","engagement"],type:"mc",q:"A newly identified regulator has high influence but little knowledge of the project. What should the project manager do first?",opts:["Send the full project repository","Analyze the regulator’s needs and update the engagement approach","Ask the sponsor to handle all communication","Wait until a formal inspection is scheduled"],ans:[1],why:["Thông tin quá tải chưa chắc đúng nhu cầu.","Đúng: phân tích trước rồi tailor engagement.","PM vẫn phải quản lý stakeholder.","Chờ đợi làm tăng compliance risk."],exp:"P4 bắt đầu bằng nhận diện và phân tích stakeholder, rồi mới chọn thông điệp/kênh."},{id:"o205",n:205,t:0,origin:"original",eco:"P5",domain:"people",approach:"hybrid",tags:["expectations","alignment"],type:"mc",q:"The sponsor expects a nationwide launch while the product owner believes the approved release is a regional pilot. What should the project manager do?",opts:["Use the sponsor’s expectation because the sponsor funds the project","Facilitate a discussion using the charter and release objectives to align expectations","Let both plans continue until the first release","Ask the team to build capacity for both outcomes"],ans:[1],why:["Quyền lực không thay thế phạm vi đã thống nhất.","Đúng: làm rõ điểm lệch và chốt kỳ vọng chung.","Hai kế hoạch mâu thuẫn tạo lãng phí.","Đội không nên gánh hậu quả của kỳ vọng chưa căn chỉnh."],exp:"P5 khác P6 ở chỗ trọng tâm là **căn chỉnh kỳ vọng đang khác nhau**, trước khi quản lý mức hài lòng liên tục."},{id:"o206",n:206,t:0,origin:"original",eco:"P6",domain:"people",approach:"agile",tags:["satisfaction","feedback"],type:"mc",q:"Sprint reviews show all acceptance criteria are met, but customer satisfaction has declined for three releases. What should the project manager do next?",opts:["Increase velocity targets","Meet customers to understand the expectation gap and adapt outcomes","Tighten the definition of done without customer input","Report that delivery is successful because scope is complete"],ans:[1],why:["Velocity không đo customer value.","Đúng: tìm khoảng cách kỳ vọng và phản hồi.","DoD nội bộ không thay thế tiếng nói khách hàng.","Output hoàn thành không đồng nghĩa outcome tốt."],exp:"P6 yêu cầu theo dõi và phản ứng với kỳ vọng/satisfaction, kể cả khi delivery metrics đẹp."},{id:"o207",n:207,t:0,origin:"original",eco:"P7",domain:"people",approach:"predictive",tags:["knowledge-transfer","transition"],type:"mc",q:"A specialist will leave in two weeks and owns a critical deployment procedure. Which action best ensures knowledge transfer?",opts:["Ask the specialist to upload existing files","Pair the specialist with successors, rehearse the procedure, and record gaps","Hire a replacement after the specialist leaves","Add knowledge loss to the issue log only"],ans:[1],why:["Tài liệu không chứng minh người nhận làm được.","Đúng: chuyển giao có thực hành và kiểm chứng.","Quá muộn và không bảo toàn tri thức.","Ghi nhận mà không hành động là chưa đủ."],exp:"Knowledge transfer hoàn tất khi người nhận có thể áp dụng, không chỉ khi tài liệu đã được lưu."},{id:"o208",n:208,t:0,origin:"original",eco:"P8",domain:"people",approach:"hybrid",tags:["communication","reporting"],type:"mc",q:"Executives want monthly benefit forecasts while the delivery team needs daily blocker visibility. What should the project manager do?",opts:["Use one detailed daily report for everyone","Tailor content, channel, and cadence to each audience and establish feedback","Report only to executives because they have more influence","Let each audience independently request information"],ans:[1],why:["Một format không phục vụ hai nhu cầu khác nhau.","Đúng: communication strategy phải tailored và two-way.","Bỏ đội làm chậm xử lý blocker.","Thụ động và không tạo vòng phản hồi."],exp:"P8 kiểm tra người nào cần thông tin gì, lúc nào, qua kênh nào và phản hồi ra sao."},{id:"o209",n:209,t:0,origin:"original",eco:"R1",domain:"process",approach:"hybrid",tags:["integrated-plan","lifecycle"],type:"mc",q:"Hardware requirements are stable, but the customer-facing software needs frequent feedback. Which delivery approach should the project manager recommend?",opts:["Predictive for all work","Agile for all work regardless of dependencies","Hybrid: predictive hardware planning with iterative software delivery","No formal approach until execution begins"],ans:[2],why:["Bỏ lỡ feedback sớm cho software.","Không phù hợp phần cứng có phụ thuộc và lead time ổn định.","Đúng: tailor approach theo từng phần và tích hợp phụ thuộc.","Approach cần được xác định để lập kế hoạch delivery."],exp:"R1 yêu cầu đánh giá nhu cầu/độ phức tạp và chọn approach phù hợp, không áp một mô hình cho toàn bộ dự án."},{id:"o210",n:210,t:0,origin:"original",eco:"R2",domain:"process",approach:"predictive",tags:["scope","wbs"],type:"mc",q:"Stakeholders approved high-level scope for a predictive project. What should the team do next to make the work manageable?",opts:["Decompose deliverables into a work breakdown structure","Begin work on the easiest deliverable","Create a product backlog and skip scope baseline","Request final acceptance"],ans:[0],why:["Đúng: phân rã scope thành work packages có thể ước lượng/quản lý.","Dễ không đồng nghĩa đúng thứ tự phụ thuộc.","Có thể dùng backlog trong bối cảnh phù hợp nhưng không nên bỏ baseline đã chọn.","Acceptance diễn ra sau khi deliverables hoàn thành."],exp:"Với predictive scope đã thống nhất, decomposition/WBS là bước tự nhiên tiếp theo."},{id:"o211",n:211,t:0,origin:"original",eco:"R3",domain:"process",approach:"agile",tags:["value","prioritization"],type:"mc",q:"A team can release either a popular low-risk feature or a compliance feature required before revenue can be recognized. How should the product owner prioritize?",opts:["Always choose the most popular feature","Prioritize the compliance enabler because it unlocks business value","Split capacity equally without analyzing dependencies","Choose the feature with the largest story-point estimate"],ans:[1],why:["Popularity không phản ánh điều kiện tạo giá trị.","Đúng: compliance item là enabler cho revenue/value.","Chia đều có thể trì hoãn cả hai.","Story points là effort, không phải value."],exp:"Value-based delivery xét cả dependency, risk và khả năng mở khóa lợi ích, không chỉ customer preference."},{id:"o212",n:212,t:0,origin:"original",eco:"R4",domain:"process",approach:"agile",tags:["resources","capacity"],type:"mc",q:"A cross-functional team lacks security expertise for the next two iterations. What should the project manager do first?",opts:["Commit the work and expect overtime","Assess the skill need and collaborate on training, pairing, or temporary support","Remove security acceptance criteria","Transfer all security work to the product owner"],ans:[1],why:["Tạo burnout và vẫn không có năng lực.","Đúng: xác định gap rồi tối ưu nguồn lực/capability.","Làm giảm chất lượng và compliance.","PO không thay thế chuyên môn delivery."],exp:"R4 quản lý cả số lượng lẫn capability và availability của nguồn lực."},{id:"o213",n:213,t:0,origin:"original",eco:"R5",domain:"process",approach:"predictive",tags:["procurement","contract"],type:"mc",q:"A buyer has a well-defined scope and wants to transfer most cost-overrun risk to the seller. Which contract type is most suitable?",opts:["Cost-reimbursable","Time and materials","Firm-fixed-price","Informal verbal agreement"],ans:[2],why:["Buyer giữ phần lớn cost risk.","Phù hợp khi scope/khối lượng chưa chắc, không tối ưu yêu cầu này.","Đúng: scope rõ và seller nhận cost-overrun risk.","Không đủ governance/protection."],exp:"Contract type phân bổ risk khác nhau; fixed price hợp hơn khi scope đủ rõ."},{id:"o214",n:214,t:0,origin:"original",eco:"R6",domain:"process",approach:"predictive",tags:["finance","reserve"],type:"mc",q:"An identified risk occurs and the approved response requires funds. Which source should normally be used first?",opts:["Contingency reserve allocated for identified risks","Management reserve without approval","The project manager’s personal discretion outside the budget","Future operational budget"],ans:[0],why:["Đúng: contingency reserve dành cho known-unknowns đã nhận diện.","Management reserve cho unknown-unknowns và theo governance.","Không có khái niệm ngân sách ngoài kiểm soát.","Không chuyển chi phí dự án tùy tiện sang operations."],exp:"Phân biệt contingency reserve (identified risk, nằm trong cost baseline) và management reserve (ngoài baseline, cần governance)."},{id:"o215",n:215,t:0,origin:"original",eco:"R7",domain:"process",approach:"agile",tags:["quality","acceptance-criteria"],type:"mc",q:"Defects repeatedly pass development and are found only during sprint review. What should the team do?",opts:["Add more inspectors at the end","Analyze the cause and strengthen quality criteria/checks earlier in the workflow","Reduce the number of sprint reviews","Accept defects when velocity is high"],ans:[1],why:["End inspection không phòng ngừa.","Đúng: build quality in và cải tiến process.","Giảm feedback làm vấn đề tệ hơn.","Velocity không bù chất lượng kém."],exp:"R7 ưu tiên phòng ngừa, tiêu chí rõ và kiểm tra sớm; sau đó dùng RCA để ngăn lỗi lặp."},{id:"o216",n:216,t:0,origin:"original",eco:"R8",domain:"process",approach:"hybrid",tags:["schedule","dependency"],type:"mc",q:"A regulatory review on the critical path may finish two weeks late. What should the project manager do first?",opts:["Immediately crash all downstream work","Assess the dependency and schedule impact, then evaluate response options","Hide the delay until it is certain","Remove the review milestone"],ans:[1],why:["Nén lịch trước phân tích có thể tăng chi phí vô ích.","Đúng: hiểu impact trước khi chọn response.","Thiếu minh bạch.","Không thể bỏ milestone bắt buộc."],exp:"R8 theo mẫu assess → options → decision; schedule compression không phải phản xạ đầu tiên."},{id:"o217",n:217,t:0,origin:"original",eco:"R9",domain:"process",approach:"agile",tags:["metrics","status"],type:"mc",q:"Velocity increased 20%, but escaped defects and customer complaints also increased. How should the project manager report status?",opts:["Report green because velocity improved","Use balanced delivery, quality, and outcome metrics and explain the trade-off","Stop reporting velocity permanently","Report only the defect count"],ans:[1],why:["Một metric tạo kết luận sai.","Đúng: status phải phản ánh nhiều chiều và hỗ trợ quyết định.","Velocity vẫn hữu ích đúng ngữ cảnh.","Chỉ defect cũng thiếu delivery/value context."],exp:"R9 không tối ưu một con số; artifacts và metrics được tailor để phản ánh tình trạng thật."},{id:"o218",n:218,t:0,origin:"original",eco:"R10",domain:"process",approach:"hybrid",tags:["closure","transition"],type:"mc",q:"The product is accepted, but the operations team has not completed support training. What should the project manager do before closure?",opts:["Close because customer acceptance is sufficient","Validate transition readiness and complete the agreed handover activities","Transfer the unresolved work to the issue log and close","Ask the sponsor to waive operational readiness"],ans:[1],why:["Acceptance chỉ là một điều kiện đóng.","Đúng: transition readiness phải được xác nhận.","Chuyển log không bảo đảm vận hành được.","Waiver không nên thay thế trách nhiệm bàn giao nếu chưa có phân tích/governance."],exp:"R10 bao gồm acceptance, transition, tài chính/hợp đồng, lessons learned và release resources."},{id:"o219",n:219,t:0,origin:"original",eco:"B1",domain:"business",approach:"predictive",tags:["governance","threshold"],type:"mc",q:"A change exceeds the project manager’s approved cost threshold. What should the project manager do?",opts:["Approve it because schedule impact is small","Follow the defined governance escalation path for a decision","Ask the team to absorb the cost secretly","Reject every change above the threshold"],ans:[1],why:["Vượt thẩm quyền.","Đúng: governance quy định decision rights và escalation.","Vi phạm transparency/baseline.","Vượt threshold cần cấp có quyền quyết, không tự động bị từ chối."],exp:"B1 là decision system: cấu trúc, ngưỡng, escalation và success metrics."},{id:"o220",n:220,t:0,origin:"original",eco:"B2",domain:"business",approach:"agile",tags:["compliance","security"],type:"mc",q:"A new privacy rule becomes effective before the next release. The backlog does not include required consent changes. What should happen first?",opts:["Release as planned and fix it later","Confirm the compliance requirement and analyze its impact with relevant experts","Let developers interpret the regulation independently","Remove analytics features without analysis"],ans:[1],why:["Có thể gây noncompliance.","Đúng: xác nhận nghĩa vụ và impact trước khi hành động.","Cần legal/privacy expertise và thống nhất.","Hành động cực đoan khi chưa hiểu yêu cầu."],exp:"B2: confirm/classify compliance → assess threats/consequences → select action → measure compliance."},{id:"o221",n:221,t:0,origin:"original",eco:"B3",domain:"business",approach:"hybrid",tags:["change-control","baseline"],type:"mc",q:"An executive requests a major feature and says formal approval can follow after development starts. What should the project manager do?",opts:["Start immediately because the requester is an executive","Record the request, assess impact, and route it through the agreed change process","Ask the team to work on it unofficially","Reject it because baselines can never change"],ans:[1],why:["Chức vụ không xóa governance.","Đúng: analyze/approve trước implement.","Shadow work phá transparency và capacity.","Baseline có thể đổi qua control process."],exp:"B3 nhấn mạnh thứ tự request → impact → approval → implementation → documentation/communication."},{id:"o222",n:222,t:0,origin:"original",eco:"B4",domain:"business",approach:"agile",tags:["impediment","issue"],type:"mc",q:"A test environment outage is blocking the entire team today. What should the project manager do?",opts:["Log it as a future risk and continue normal work","Make the blocker visible, assess impact, assign ownership, and coordinate removal","Wait for the next retrospective","Increase the sprint commitment"],ans:[1],why:["Đây đã là issue/impediment, không còn future risk.","Đúng: ưu tiên blocker hiện tại và phối hợp gỡ.","Retro quá muộn cho blocker đang dừng đội.","Tăng commitment làm tình hình tệ hơn."],exp:"B4 phân biệt risk chưa xảy ra với issue/impediment hiện tại và hành động theo mức ảnh hưởng."},{id:"o223",n:223,t:0,origin:"original",eco:"B5",domain:"business",approach:"hybrid",tags:["risk","trigger"],type:"mc",q:"A supplier delay risk has a documented trigger and response owner. The trigger occurs. What should the project manager do next?",opts:["Close the risk without action","Execute the planned response, manage it as an issue, and communicate impact","Create a new unrelated risk register","Wait for the schedule variance report"],ans:[1],why:["Trigger xảy ra nghĩa là cần hành động.","Đúng: response plan được thực thi và risk chuyển thành issue.","Không giải quyết tình huống.","Chờ báo cáo làm mất thời gian response."],exp:"Risk monitoring phải nối trigger với owner/action; khi sự kiện xảy ra, theo dõi như issue."},{id:"o224",n:224,t:0,origin:"original",eco:"B6",domain:"business",approach:"agile",tags:["continuous-improvement","retrospective"],type:"mc",q:"Three retrospectives identified the same review bottleneck, but cycle time has not improved. What should the project manager do next?",opts:["Document the lesson again","Help the team select one process experiment, define a measure, and review the result","Stop retrospectives because they are ineffective","Replace the reviewers immediately"],ans:[1],why:["Ghi lại lần nữa không tạo thay đổi.","Đúng: lesson phải thành thử nghiệm đo được.","Vấn đề là thiếu follow-through, không phải bản thân retrospective.","Thay người trước RCA là quá sớm."],exp:"B6 lấp khoảng trống của ngân hàng cũ: continuous improvement = insight → experiment/change → measurement → standardize or adjust."},{id:"o225",n:225,t:0,origin:"original",eco:"B7",domain:"business",approach:"hybrid",tags:["organizational-change","adoption"],type:"mc",q:"Users attended training for a new workflow but continue using the legacy process. What should the project manager do first?",opts:["Schedule the same training again","Assess cultural, incentive, and workflow barriers to adoption","Disable the legacy system immediately","Report users as resistant and close the project"],ans:[1],why:["Lặp cùng giải pháp khi chưa rõ nguyên nhân.","Đúng: tìm adoption barriers rồi tailor support.","Có thể gây operational harm nếu chưa sẵn sàng.","Gắn nhãn không giải quyết thay đổi tổ chức."],exp:"B7 nhìn adoption như thay đổi hành vi/hệ thống; training chỉ là một can thiệp."},{id:"o226",n:226,t:0,origin:"original",eco:"B8",domain:"business",approach:"agile",tags:["external-change","market"],type:"mc",q:"A competitor launches a free alternative that invalidates a key revenue assumption in the product business case. What should the project manager do?",opts:["Continue the backlog unchanged to protect the baseline","Assess the external change with stakeholders and reprioritize scope/backlog based on value","Copy the competitor’s features immediately","Cancel the project without governance review"],ans:[1],why:["Business assumption đã đổi nên backlog cần review.","Đúng: survey → assess impact → adapt with stakeholders.","Phản ứng sao chép chưa có value analysis.","PM không tự ý cancel ngoài governance."],exp:"B8 yêu cầu theo dõi môi trường ngoài và phản ánh tác động vào business case, scope hoặc backlog."}],q={"P1::Facilitate alignment on one measurable vision and confirm shared understanding":{correct:!0,why:"Quản lý dự án cần đưa các bên vào cùng một cuộc trao đổi để thống nhất một kết quả có thể đo lường, rồi kiểm tra rằng mọi người hiểu theo cùng một cách. Cách này biến bất đồng về thành công thành tiêu chí chung để nhóm ra quyết định và phối hợp.",exp:"Trước hết làm rõ các cách hiểu khác nhau về giá trị; tiếp đó cùng các bên liên quan chốt một mục tiêu đo được và ghi lại tiêu chí thành công. Cuối cùng yêu cầu các bên diễn đạt lại thỏa thuận để phát hiện hiểu sai trước khi triển khai."},"P1::Elicit each perspective, identify common value, and document an agreed vision":{correct:!0,why:"Việc lắng nghe từng góc nhìn giúp phân biệt lợi ích thật với các yêu cầu cục bộ. Quản lý dự án sau đó cần tổng hợp phần giá trị chung thành một tầm nhìn được các bên cùng xác nhận và lưu lại để làm căn cứ phối hợp.",exp:"Thu thập các quan điểm mà không vội chọn bên; tìm điểm giao về giá trị mà dự án phải tạo ra. Chuyển điểm giao đó thành tầm nhìn rõ ràng, xin xác nhận và cập nhật tài liệu dùng chung."},"P1::Use the charter and expected outcomes to build and validate a common vision":{correct:!0,why:"Điều lệ và kết quả kỳ vọng cung cấp căn cứ chính thức để kiểm tra các cách hiểu đang khác nhau. Dùng chúng để xây dựng rồi xác nhận một tầm nhìn chung giúp quyết định dựa trên mục tiêu dự án thay vì vị thế của từng người.",exp:"Đối chiếu các ý kiến với điều lệ và kết quả đã được phê duyệt; loại bỏ phần không phục vụ mục tiêu chung. Sau đó tổ chức xác nhận với các bên và dùng tầm nhìn đã thống nhất làm chuẩn cho phạm vi, ưu tiên và nghiệm thu."},"P1::Ask the most senior sponsor to choose the vision alone":{correct:!1,why:"Trao toàn bộ việc chọn tầm nhìn cho người có chức vụ cao nhất bỏ qua kiến thức của các nhóm thực hiện và lợi ích của các bên khác. Quyết định áp đặt có thể tạo vẻ đồng thuận tạm thời nhưng dễ dẫn đến phản đối, diễn giải khác nhau và làm lại."},"P1::Let each team keep its own definition of success":{correct:!1,why:"Cho mỗi nhóm giữ một định nghĩa thành công riêng sẽ biến mục tiêu chung thành nhiều mục tiêu cạnh tranh. Các nhóm có thể tối ưu phần việc của mình nhưng tạo ra sản phẩm không đáp ứng cùng một kết quả kinh doanh và không có tiêu chí nghiệm thu thống nhất."},"P1::Start delivery and resolve the disagreement after the first release":{correct:!1,why:"Bắt đầu khi các bên còn bất đồng sẽ đưa giả định chưa được kiểm chứng vào thiết kế và cam kết. Khi sai lệch chỉ lộ ra ở bản phát hành đầu tiên, chi phí đổi hướng và làm lại sẽ cao hơn nhiều so với việc căn chỉnh trước."},"P1::Convert every opinion directly into a separate requirement":{correct:!1,why:"Biến mọi ý kiến thành yêu cầu làm phình phạm vi mà không phân biệt giá trị, phụ thuộc hay mâu thuẫn. Cách đó không giải quyết câu hỏi dự án cần đạt kết quả nào và khiến nhóm phải thực hiện những yêu cầu không thể cùng tồn tại."},"P1::Escalate the disagreement before facilitating a discussion":{correct:!1,why:"Leo thang ngay trước khi tìm hiểu các lợi ích và điểm bất đồng sẽ đẩy một vấn đề có thể giải quyết bằng đối thoại lên cấp quản trị. Người nhận escalation cũng thiếu thông tin để quyết định, còn các bên không học được cách thống nhất mục tiêu."},"P1::Measure team utilization instead of clarifying outcomes":{correct:!1,why:"Mức sử dụng nhân lực chỉ cho biết nhóm đang bận đến đâu, không cho biết các nhóm đang hướng tới cùng một giá trị hay không. Tối ưu chỉ số này có thể làm tăng hoạt động nhưng vẫn giữ nguyên mâu thuẫn về kết quả cần đạt."},"P2::Meet the parties, understand the source of conflict, and facilitate a collaborative resolution":{correct:!0,why:"Quản lý dự án nên gặp các bên để tìm nguyên nhân, lợi ích và dữ kiện phía sau lập trường, rồi điều phối họ xây dựng cách giải quyết mà cả hai có thể thực hiện. Như vậy xung đột được xử lý ở gốc thay vì chỉ làm im tiếng tranh luận.",exp:"Trước tiên lắng nghe từng bên riêng và cùng họ xác định vấn đề thực; tiếp đó làm rõ lợi ích, ranh giới và phương án có thể chấp nhận. Cuối cùng thống nhất hành động, người chịu trách nhiệm và cách kiểm tra kết quả."},"P2::Reinforce agreed ground rules and help the parties focus on interests rather than positions":{correct:!0,why:"Nhắc lại quy tắc làm việc đã thống nhất giúp cuộc trao đổi an toàn và tôn trọng. Chuyển từ bảo vệ lập trường sang khám phá lợi ích cho phép các bên tìm phương án đáp ứng nhu cầu thực thay vì tranh thắng thua.",exp:"Khôi phục quy tắc đối thoại trước khi bàn giải pháp; yêu cầu mỗi bên giải thích điều họ cần bảo vệ. So sánh các lợi ích đó, tìm phương án dung hòa và xác nhận cam kết thực hiện."},"P2::Create a safe conversation, listen to each perspective, and agree on a workable resolution":{correct:!0,why:"Một cuộc trò chuyện an toàn làm tăng khả năng các bên nói ra dữ kiện và mối lo thật. Lắng nghe đủ các góc nhìn rồi chốt một giải pháp khả thi giúp khôi phục hợp tác mà không phủ nhận khác biệt.",exp:"Bảo đảm không gian trao đổi không đổ lỗi và cho mỗi bên thời gian trình bày; tóm tắt để xác nhận đã hiểu đúng. Sau đó cùng chọn giải pháp có thể thực hiện, ghi rõ hành động và theo dõi sự cải thiện."},"P2::Escalate immediately to both functional managers":{correct:!1,why:"Leo thang ngay sẽ bỏ qua việc tìm nguyên nhân và có thể biến bất đồng chuyên môn thành tranh chấp quyền lực giữa các quản lý chức năng. Nó cũng làm chậm quyết định và không tạo thỏa thuận làm việc giữa hai người trực tiếp phối hợp."},"P2::Remove one party before investigating the conflict":{correct:!1,why:"Loại một người trước khi tìm hiểu sự việc là kết luận dựa trên giả định, có thể mất năng lực cần thiết và làm suy giảm niềm tin. Nguyên nhân về mục tiêu, vai trò hoặc lợi ích vẫn còn nên xung đột dễ tái diễn với người khác."},"P2::Ignore the tension because technical results matter more":{correct:!1,why:"Bỏ qua căng thẳng làm giảm trao đổi thông tin và khiến vấn đề kỹ thuật bị che khuất hoặc xử lý chậm. Kết quả ngắn hạn không bù được chi phí phối hợp, tinh thần đội nhóm và nguy cơ xung đột bùng phát lớn hơn."},"P2::Vote on which person is right":{correct:!1,why:"Bỏ phiếu chọn người đúng biến vấn đề cần hiểu và hợp tác thành cuộc thi số đông. Quyết định có thể bỏ qua dữ kiện hoặc lợi ích chính đáng của thiểu số và không tạo cam kết giải quyết nguyên nhân."},"P2::Force a compromise without hearing the underlying interests":{correct:!1,why:"Ép một thỏa hiệp khi chưa biết mỗi bên thực sự cần gì chỉ tạo sự nhượng bộ bề ngoài. Các bên có thể tuân thủ miễn cưỡng, rồi quay lại tranh chấp khi điều kiện thay đổi vì vấn đề gốc chưa được giải quyết."},"P2::Cancel collaboration meetings until the conflict disappears":{correct:!1,why:"Hủy các cuộc họp loại bỏ kênh giải quyết thay vì giải quyết xung đột, đồng thời làm chậm công việc phụ thuộc vào quyết định chung. Tránh mặt không khiến lợi ích mâu thuẫn biến mất và còn làm suy giảm niềm tin."},"P3::Assess team maturity, clarify decision boundaries, and adapt the leadership style":{correct:!0,why:"Đánh giá mức trưởng thành cho biết nhóm cần hướng dẫn đến đâu và có thể tự quyết việc gì. Làm rõ ranh giới quyết định rồi điều chỉnh cách lãnh đạo giúp vừa trao quyền vừa giữ trách nhiệm, tránh cả kiểm soát vi mô lẫn bỏ mặc.",exp:"Xác định năng lực, mức tự chủ và loại quyết định nhóm đã sẵn sàng đảm nhận; sau đó ghi rõ quyền hạn và điểm cần báo cáo. Chọn mức huấn luyện, hỗ trợ hoặc ủy quyền phù hợp rồi xem xét lại khi nhóm tiến bộ."},"P3::Coach the team and delegate decisions at the level they are prepared to own":{correct:!0,why:"Huấn luyện giúp nhóm nâng năng lực thay vì phụ thuộc lâu dài vào quản lý. Ủy quyền đúng mức tạo cơ hội sở hữu quyết định, trong khi giới hạn rõ ràng bảo vệ chất lượng và trách nhiệm quản trị.",exp:"Xác định khoảng trống năng lực và hướng dẫn qua các quyết định thực tế; bắt đầu ủy quyền ở phạm vi nhóm đủ sức chịu trách nhiệm. Kiểm tra kết quả, phản hồi và mở rộng quyền khi năng lực đã được chứng minh."},"P3::Use servant leadership to remove constraints while keeping accountability clear":{correct:!0,why:"Lãnh đạo phục vụ tập trung gỡ trở ngại để đội tự hoàn thành công việc, không lấy đi quyền sở hữu của đội. Giữ rõ người chịu trách nhiệm và tiêu chí kết quả giúp hỗ trợ không biến thành buông lỏng.",exp:"Hỏi nhóm đang bị cản bởi điều gì, xử lý các phụ thuộc nằm ngoài quyền của họ và để họ quyết định phần việc thuộc phạm vi. Đồng thời giữ cam kết, tiêu chí kết quả và cơ chế phản hồi minh bạch."},"P3::Approve every decision personally to retain control":{correct:!1,why:"Duyệt mọi quyết định nhỏ tạo nút thắt ở quản lý và làm nhóm mất cơ hội phát triển năng lực. Nó cũng truyền đi rằng trách nhiệm không được phân bổ, khiến tốc độ và động lực suy giảm."},"P3::Delegate governance decisions without any boundaries":{correct:!1,why:"Ủy quyền quyết định quản trị mà không đặt ngưỡng, vai trò hoặc cơ chế báo cáo tạo khoảng trống kiểm soát. Nhóm có thể cam kết vượt thẩm quyền hoặc đưa ra quyết định không phù hợp với lợi ích toàn dự án."},"P3::Replace the team lead immediately":{correct:!1,why:"Thay người ngay khi chưa tìm hiểu nguyên nhân có thể loại bỏ một người có năng lực và không giải quyết vấn đề về huấn luyện, quyền hạn hoặc kỳ vọng. Quyết định nhân sự như vậy còn làm giảm an toàn tâm lý của cả nhóm."},"P3::Set higher utilization targets to improve motivation":{correct:!1,why:"Tăng mục tiêu sử dụng nhân lực đo mức bận rộn chứ không giải quyết nhu cầu được hỗ trợ, công nhận hay tự chủ. Áp lực thêm có thể làm kiệt sức và khiến nhóm tập trung vào số giờ thay vì kết quả."},"P3::Assign all decisions to the most senior technical expert":{correct:!1,why:"Thâm niên kỹ thuật không tự động trao quyền quyết định về ưu tiên, con người hay quản trị. Tập trung mọi quyết định vào một chuyên gia tạo phụ thuộc và bỏ qua tiếng nói của những người chịu trách nhiệm thực hiện."},"P3::Avoid feedback so the team can self-organize":{correct:!1,why:"Tự tổ chức không đồng nghĩa với không cần phản hồi; thiếu phản hồi khiến nhóm không biết ranh giới hoặc hành vi nào cần điều chỉnh. Sai lệch chỉ được phát hiện muộn, khi việc sửa hướng khó và tốn kém hơn."},"P4::Analyze the stakeholder’s needs and tailor an engagement approach":{correct:!0,why:"Phân tích nhu cầu cho biết bên liên quan cần thông tin, quyết định hay mức tham gia nào, thay vì gửi cùng một nội dung cho mọi người. Cách tiếp cận được điều chỉnh theo ảnh hưởng, mối quan tâm và phản hồi sẽ tăng khả năng họ ủng hộ dự án.",exp:"Xác định quyền lợi, ảnh hưởng, kiến thức hiện tại và điều họ cần để hành động; sau đó chọn kênh, tần suất và người trao đổi phù hợp. Theo dõi phản hồi và cập nhật cách tiếp cận khi nhu cầu thay đổi."},"P4::Meet the stakeholder, listen to concerns, and update the engagement strategy":{correct:!0,why:"Gặp trực tiếp và lắng nghe mối lo giúp quản lý dự án phân biệt vấn đề thật với giả định trong hồ sơ. Cập nhật chiến lược sau cuộc trao đổi biến thông tin mới thành hành động tương tác cụ thể.",exp:"Chuẩn bị câu hỏi mở và xác nhận điều bên liên quan quan tâm; ghi lại khoảng cách giữa mức tham gia hiện tại và mức cần thiết. Chọn hành động cải thiện rồi hẹn kiểm tra phản hồi thay vì coi cuộc gặp là kết thúc."},"P4::Assess influence, interest, and current engagement before selecting communication actions":{correct:!0,why:"Đánh giá ảnh hưởng, mối quan tâm và mức tham gia hiện tại giúp quyết định ai cần được trao đổi sâu, ai cần cập nhật định kỳ và ai có thể hỗ trợ. Làm việc này trước khi chọn kênh tránh lãng phí thông tin và giảm nguy cơ bỏ sót người có tác động lớn.",exp:"Lập bức tranh stakeholder dựa trên ảnh hưởng, lợi ích và hành vi hiện tại; xác định khoảng cách cần thu hẹp. Sau đó chọn nội dung, kênh và nhịp trao đổi, rồi kiểm chứng hiệu quả qua phản hồi."},"P4::Send the complete project repository without assessing needs":{correct:!1,why:"Gửi toàn bộ kho tài liệu đẩy gánh nặng chọn lọc sang stakeholder và không bảo đảm họ tìm được thông tin cần thiết. Quá nhiều nội dung còn có thể che khuất rủi ro hoặc khiến họ hiểu sai vì thiếu bối cảnh."},"P4::Ask the sponsor to handle all engagement":{correct:!1,why:"Giao toàn bộ tương tác cho sponsor bỏ qua trách nhiệm hiểu và quản lý stakeholder của nhóm dự án. Sponsor có thể không biết chi tiết nhu cầu hằng ngày, còn các vấn đề không được phản hồi trực tiếp sẽ tích tụ."},"P4::Wait until the stakeholder formally complains":{correct:!1,why:"Chờ khi có khiếu nại nghĩa là bỏ qua tín hiệu sớm và để khoảng cách tham gia trở nên khó sửa. Khi phản ứng chính thức xuất hiện, niềm tin và thời gian xử lý đã bị tiêu hao."},"P4::Classify the stakeholder once and never revisit the assessment":{correct:!1,why:"Ảnh hưởng, mối quan tâm và thái độ của stakeholder thay đổi theo giai đoạn dự án. Giữ nguyên phân loại khiến chiến lược cũ không còn phù hợp và có thể bỏ lỡ người đang trở nên quan trọng."},"P4::Use the same weekly report for every stakeholder":{correct:!1,why:"Một báo cáo giống nhau không đáp ứng khác biệt về quyết định, mức chi tiết và nhịp thông tin của từng người. Báo cáo có thể dài nhưng vẫn không giúp đúng stakeholder hành động đúng lúc."},"P4::Reduce contact to avoid additional requirements":{correct:!1,why:"Giảm tiếp xúc để né yêu cầu không loại bỏ nhu cầu của stakeholder mà chỉ làm chúng xuất hiện muộn và khó kiểm soát hơn. Thiếu đối thoại còn làm tăng giả định, bất ngờ và nguy cơ phản đối khi bàn giao."},"P5::Facilitate a discussion using approved objectives to align and document expectations":{correct:!0,why:"Quản lý dự án cần đưa các bên trở lại mục tiêu đã phê duyệt, làm rõ điểm khác nhau và điều phối họ chốt kỳ vọng có thể thực hiện. Ghi lại thỏa thuận giúp đội có một căn cứ thống nhất thay vì dựa vào cách hiểu riêng.",exp:"Đối chiếu từng kỳ vọng với mục tiêu, phạm vi và tiêu chí thành công đã duyệt; làm rõ tác động của các lựa chọn. Sau đó chốt kết quả chung, người phê duyệt và tài liệu tham chiếu để ngăn diễn giải lại."},"P5::Make the expectation gap visible and obtain agreement on one achievable outcome":{correct:!0,why:"Nêu rõ khoảng cách giữa các kỳ vọng giúp mọi người thấy vì sao không thể đồng thời theo đuổi các kết quả mâu thuẫn. Chốt một kết quả khả thi tạo cam kết thực tế và bảo vệ đội khỏi lời hứa vượt năng lực.",exp:"Lập bảng so sánh kỳ vọng, giả định và giới hạn; xác định phần chênh lệch cần quyết định. Trình bày các phương án và cùng stakeholder chọn một kết quả có thể đạt, đo lường và nghiệm thu."},"P5::Clarify assumptions, constraints, and success criteria with the affected stakeholders":{correct:!0,why:"Làm rõ giả định, ràng buộc và tiêu chí thành công khiến các bên nhìn cùng một bức tranh về điều được cam kết. Đây là nền tảng để phát hiện kỳ vọng không thực tế trước khi chúng biến thành tranh chấp bàn giao.",exp:"Hỏi từng stakeholder điều họ đang giả định và bằng chứng nào chứng minh thành công; ghi lại giới hạn về thời gian, phạm vi và nguồn lực. Sau đó xác nhận bộ tiêu chí chung và cập nhật kế hoạch theo thỏa thuận."},"P5::Use the expectation of the most senior stakeholder":{correct:!1,why:"Chức vụ cao nhất không biến một kỳ vọng cá nhân thành mục tiêu đã được phê duyệt. Bỏ qua stakeholder khác có thể tạo phản đối, phạm vi không khả thi và trách nhiệm không rõ khi kết quả không đáp ứng người sử dụng."},"P5::Let both interpretations continue until acceptance":{correct:!1,why:"Để hai cách hiểu cùng tồn tại trì hoãn quyết định và khiến nhóm xây dựng dựa trên các tiêu chí nghiệm thu khác nhau. Đến lúc bàn giao, bất đồng đã trở thành tranh chấp tốn kém thay vì vấn đề có thể giải quyết sớm."},"P5::Ask the team to build for every possible expectation":{correct:!1,why:"Xây cho mọi kỳ vọng biến sự không thống nhất thành phạm vi vô hạn, làm loãng giá trị và vượt thời gian hoặc ngân sách. Nhóm cần một kết quả ưu tiên được thống nhất, không phải sản phẩm cố đáp ứng mọi mong muốn."},"P5::Treat a distributed document as proof of agreement":{correct:!1,why:"Một tài liệu được phát tán chỉ chứng minh thông tin đã được gửi, không chứng minh các bên đã đọc, hiểu và đồng ý. Nếu không có trao đổi và xác nhận, những giả định khác nhau vẫn có thể chi phối quyết định."},"P5::Promise the larger outcome before impact analysis":{correct:!1,why:"Hứa kết quả lớn hơn trước khi phân tích tác động biến kỳ vọng chưa kiểm chứng thành cam kết. Khi phát hiện thiếu nguồn lực hoặc xung đột mục tiêu, dự án phải rút lời hứa và mất niềm tin."},"P5::Postpone alignment until final delivery":{correct:!1,why:"Trì hoãn căn chỉnh đến khi bàn giao khiến đội đầu tư nhiều công sức theo kỳ vọng sai. Chi phí sửa phạm vi, thiết kế và kế hoạch lúc đó cao hơn nhiều so với một cuộc trao đổi ngay từ đầu."},"P6::Investigate the expectation gap with stakeholders and adapt outcomes or engagement":{correct:!0,why:"Sự hài lòng giảm dù tiêu chí nghiệm thu đạt cho thấy giá trị cảm nhận không còn khớp với điều dự án đang cung cấp. Điều tra cùng bên liên quan giúp xác định khoảng cách nằm ở nhu cầu, cách giao tiếp hay kết quả; từ đó điều chỉnh sản phẩm hoặc cách tham gia.",exp:"So sánh cam kết, kết quả thực tế và giá trị stakeholder cảm nhận; hỏi nguyên nhân thay vì suy đoán. Chọn điều chỉnh có thể tạo giá trị, cập nhật kỳ vọng và theo dõi liệu mức hài lòng có cải thiện."},"P6::Use feedback and satisfaction measures to identify what must change":{correct:!0,why:"Phản hồi và thước đo hài lòng bổ sung cho dữ liệu phạm vi và tiến độ, cho thấy người nhận đang thực sự nhận được giá trị gì. Dựa trên bằng chứng đó, quản lý dự án có thể thay đổi đúng điểm thay vì tăng hoạt động một cách mù quáng.",exp:"Thu thập phản hồi định tính cùng chỉ số hài lòng theo từng nhóm; tìm xu hướng và nguyên nhân chung. Ưu tiên thay đổi có ảnh hưởng đến giá trị, thử nghiệm và kiểm tra lại kết quả với người dùng."},"P6::Review evolving needs with customers and confirm adjusted expectations continuously":{correct:!0,why:"Nhu cầu khách hàng có thể thay đổi trong khi dự án tiến triển, nên kỳ vọng phải được rà soát chứ không được coi là cố định. Xác nhận điều chỉnh liên tục giúp nhóm ưu tiên đúng giá trị hiện tại và giảm bất ngờ ở các lần bàn giao.",exp:"Định kỳ xem lại nhu cầu, bối cảnh và tiêu chí thành công với khách hàng; ghi nhận thay đổi và tác động. Cập nhật ưu tiên hoặc cách giao tiếp, sau đó xác nhận lại kỳ vọng trước mỗi mốc quan trọng."},"P6::Report success because the baseline is green":{correct:!1,why:"Màu xanh của đường cơ sở chỉ cho biết phạm vi, thời gian hoặc chi phí đang theo kế hoạch, không chứng minh khách hàng còn nhận được giá trị. Báo cáo thành công như vậy che giấu tín hiệu hài lòng giảm và trì hoãn điều chỉnh cần thiết."},"P6::Increase delivery velocity without customer discussion":{correct:!1,why:"Tăng tốc độ giao hàng có thể tạo thêm đầu ra nhưng không trả lời vì sao khách hàng thấy giá trị giảm. Nếu không trao đổi để hiểu nhu cầu, nhóm có nguy cơ làm nhanh hơn những thứ không giải quyết vấn đề ưu tiên."},"P6::Tighten internal reporting and ignore external feedback":{correct:!1,why:"Báo cáo nội bộ chi tiết hơn không thay thế tiếng nói của người nhận sản phẩm. Bỏ qua phản hồi bên ngoài khiến dự án tối ưu theo số liệu nội bộ trong khi giá trị thực tế tiếp tục suy giảm."},"P6::Wait for final acceptance to measure satisfaction":{correct:!1,why:"Chờ đến nghiệm thu cuối mới đo hài lòng bỏ qua nhiều cơ hội học và điều chỉnh trong các phần bàn giao trước. Khi phát hiện lệch kỳ vọng, phần lớn chi phí và quyết định đã khó đảo ngược."},"P6::Add more features without identifying the gap":{correct:!1,why:"Thêm tính năng mà chưa biết khoảng cách nằm ở đâu có thể làm sản phẩm phức tạp hơn nhưng vẫn không tạo giá trị. Nó còn tiêu hao nguồn lực và làm loãng ưu tiên của khách hàng."},"P6::Tell customers their expectations cannot evolve":{correct:!1,why:"Tuyên bố kỳ vọng không được thay đổi phủ nhận thực tế kinh doanh và nhu cầu người dùng luôn biến động. Cách này biến quản lý kỳ vọng thành tranh chấp thay vì cùng tìm kết quả có giá trị và khả thi."},"P7::Pair knowledge holders with successors, practise the work, and verify capability":{correct:!0,why:"Ghép người nắm tri thức với người kế nhiệm tạo cơ hội truyền đạt trong bối cảnh thực tế, không chỉ sao chép tài liệu. Thực hành và kiểm chứng khả năng bảo đảm người nhận thật sự làm được quy trình khi chuyên gia rời đi.",exp:"Xác định quy trình quan trọng và người cần tiếp nhận; để họ cùng thực hiện công việc với chuyên gia. Quan sát một lần thực hiện độc lập, ghi lại khoảng trống và bổ sung huấn luyện trước thời hạn bàn giao."},"P7::Plan hands-on transfer, capture gaps, and store reusable knowledge":{correct:!0,why:"Kế hoạch bàn giao thực hành làm rõ thời gian, người tham gia và bằng chứng hoàn tất. Ghi nhận khoảng trống rồi lưu tri thức có thể tái sử dụng giúp tổ chức không lặp lại cùng một bài học với người kế nhiệm sau này.",exp:"Lập danh sách tri thức và hoạt động cần chuyển; tổ chức buổi làm việc có thực hành và kiểm tra. Ghi lại câu hỏi, ngoại lệ và cách xử lý, rồi đưa phiên bản đã xác nhận vào kho chung."},"P7::Identify critical knowledge early and validate that recipients can apply it":{correct:!0,why:"Nhận diện tri thức quan trọng sớm cho phép dự án xử lý rủi ro trước khi người nắm tri thức rời đi. Xác nhận người nhận áp dụng được trong tình huống thật là bằng chứng hoàn tất đáng tin cậy hơn việc chỉ có tài liệu.",exp:"Lập bản đồ điểm phụ thuộc vào cá nhân và mức độ ảnh hưởng; ưu tiên những quy trình khó thay thế. Cho người nhận thực hiện, đánh giá kết quả và chỉ đóng việc chuyển giao sau khi năng lực được chứng minh."},"P7::Ask the specialist to upload existing files only":{correct:!1,why:"Tải các tệp hiện có chỉ truyền thông tin tĩnh, không truyền các quyết định ngầm, ngoại lệ và kỹ năng thực hành. Người kế nhiệm vẫn có thể không biết áp dụng tài liệu vào tình huống thực tế."},"P7::Wait until the expert leaves before hiring a replacement":{correct:!1,why:"Chờ chuyên gia rời đi làm mất cơ hội hỏi đáp và quan sát công việc từ nguồn tri thức tốt nhất. Người thay thế sẽ phải đoán hoặc tái khám phá quy trình, làm tăng thời gian gián đoạn và sai sót."},"P7::Record knowledge loss as a risk without transfer actions":{correct:!1,why:"Ghi nhận rủi ro mà không có hoạt động chuyển giao chỉ mô tả nguy cơ, không làm giảm xác suất hay tác động. Khi sự kiện xảy ra, dự án vẫn thiếu người có thể thực hiện quy trình."},"P7::Schedule one lecture with no practice":{correct:!1,why:"Một bài giảng không kiểm tra khả năng thực hiện và thường bỏ qua ngoại lệ phát sinh trong công việc. Người nghe có thể nhớ khái niệm nhưng vẫn không vận hành được quy trình khi cần."},"P7::Store documents in a private folder owned by the departing expert":{correct:!1,why:"Kho riêng do người sắp rời đi kiểm soát tạo điểm phụ thuộc mới và có thể khiến đội mất quyền truy cập. Tri thức không được quản lý phiên bản hoặc chia sẻ để người khác tiếp tục sử dụng."},"P7::Assume experienced staff will learn the procedure independently":{correct:!1,why:"Kinh nghiệm chung không bảo đảm người mới hiểu quy trình đặc thù, các ngoại lệ và tiêu chí chất lượng. Không kiểm chứng khiến khoảng trống chỉ lộ ra khi người đó phải tự xử lý sự cố."},"P8::Tailor content, channel, cadence, and feedback to each audience":{correct:!0,why:"Lãnh đạo cần dự báo theo tháng còn nhóm cần thông tin cản trở hằng ngày, nên nội dung, kênh và nhịp gửi phải khác nhau. Thêm vòng phản hồi xác nhận thông tin giúp từng đối tượng nhận đúng điều họ cần để quyết định hoặc hành động.",exp:"Xác định quyết định mỗi nhóm cần hỗ trợ và mức chi tiết phù hợp; chọn kênh, tần suất và định dạng tương ứng. Kiểm tra người nhận đã hiểu và điều chỉnh cách truyền đạt khi phản hồi cho thấy khoảng cách."},"P8::Update the communication approach based on stakeholder information needs":{correct:!0,why:"Nhu cầu thông tin của stakeholder thay đổi theo vai trò và giai đoạn, vì vậy kế hoạch giao tiếp cần được cập nhật từ bằng chứng sử dụng và phản hồi. Cách này ưu tiên thông tin giúp ra quyết định thay vì duy trì báo cáo theo thói quen.",exp:"Rà soát ai cần thông tin gì, khi nào và để làm quyết định nào; thu thập phản hồi về mức hữu ích. Loại bỏ nội dung thừa, bổ sung thông tin còn thiếu và điều chỉnh nhịp hoặc kênh."},"P8::Confirm understanding through two-way communication rather than transmission alone":{correct:!0,why:"Gửi thông tin không chứng minh người nhận hiểu cùng một quyết định, đặc biệt khi nhóm làm việc từ xa. Trao đổi hai chiều, yêu cầu xác nhận hoặc diễn giải lại giúp phát hiện hiểu sai trước khi nó biến thành hành động sai.",exp:"Truyền đạt quyết định trong kênh phù hợp rồi mời câu hỏi và yêu cầu người chịu trách nhiệm tóm tắt hành động của họ. Làm rõ điểm lệch, ghi nhận quyết định cuối cùng và theo dõi việc thực hiện."},"P8::Send one detailed daily report to everyone":{correct:!1,why:"Một báo cáo dài hằng ngày áp cùng một tải thông tin cho người cần dự báo tháng và người cần xử lý cản trở ngay. Người nhận dễ bỏ sót tín hiệu quan trọng, còn thời gian tạo báo cáo không cải thiện quyết định."},"P8::Copy all stakeholders on every message":{correct:!1,why:"Sao chép mọi stakeholder vào mọi thư tạo nhiễu, làm lộ thông tin không cần thiết và khiến trách nhiệm phản hồi không rõ. Giao tiếp hiệu quả chọn đúng người cần biết và bảo vệ thông tin nhạy cảm."},"P8::Communicate only with high-power stakeholders":{correct:!1,why:"Chỉ nói với người có quyền lực bỏ qua người sử dụng, chuyên gia và nhóm thực hiện đang nắm thông tin vận hành. Các vấn đề có thể bị phát hiện muộn, và quyết định thiếu góc nhìn của người bị ảnh hưởng trực tiếp."},"P8::Replace conversations with a shared folder":{correct:!1,why:"Thư mục chung là nơi lưu trữ chứ không phải cơ chế xác nhận hiểu biết hay giải quyết câu hỏi. Không có trao đổi hai chiều, tài liệu dễ lỗi thời và mỗi người có thể hành động theo một cách diễn giải khác."},"P8::Increase report length without asking what decisions it supports":{correct:!1,why:"Tăng độ dài mà không hỏi báo cáo phải hỗ trợ quyết định nào chỉ làm tăng khối lượng đọc và che khuất thông tin hữu ích. Cần bắt đầu từ nhu cầu hành động rồi chọn nội dung, không phải từ số trang."},"P8::Assume silence means the message was understood":{correct:!1,why:"Im lặng có thể là chưa đọc, không đồng ý hoặc không biết phải hỏi gì, chứ không phải xác nhận hiểu. Không kiểm tra khiến hiểu sai tích tụ cho đến khi quyết định hoặc bàn giao thất bại."}},x={"R1::Assess uncertainty and dependencies, tailor the lifecycle, and integrate the plans":{correct:!0,why:"Trước khi chọn cách lập kế hoạch, quản lý dự án phải hiểu phần việc nào ổn định, phần nào còn bất định và các nhóm phụ thuộc nhau ra sao. Điều chỉnh vòng đời rồi nối các kế hoạch giúp quyết định của một nhóm không phá vỡ mốc quản trị hoặc cam kết của nhóm khác.",exp:"Đầu tiên lập bản đồ bất định, phụ thuộc và ràng buộc; sau đó chọn cách làm phù hợp cho từng loại công việc. Cuối cùng tích hợp lịch, phạm vi, quản trị và bàn giao, rồi kiểm tra lại khi dữ kiện thay đổi."},"R1::Use a hybrid approach where stable work is planned predictively and uncertain work iteratively":{correct:!0,why:"Phần cứng hoặc mốc bị quản lý chặt cần dự báo trước, còn tính năng hướng khách hàng cần vòng lặp ngắn để học từ phản hồi. Kết hợp hai cách theo đặc tính công việc giảm cả rủi ro thay đổi lẫn rủi ro thiếu kiểm soát.",exp:"Phân loại công việc theo mức ổn định và nhu cầu phản hồi; đặt kế hoạch chi tiết cho phần ổn định và chu kỳ khám phá cho phần bất định. Nối hai luồng bằng phụ thuộc, mốc tích hợp và tiêu chí quản trị chung."},"R1::Create an integrated plan that connects governance, delivery, dependencies, and change":{correct:!0,why:"Một kế hoạch tích hợp phải cho thấy quyết định quản trị ảnh hưởng thế nào đến việc giao hàng, phụ thuộc và xử lý thay đổi. Nhờ vậy nhóm nhìn được tác động liên đới thay vì tối ưu lịch riêng rồi tạo xung đột ở điểm tích hợp.",exp:"Thu thập các kế hoạch thành phần, quyền quyết định, phụ thuộc và quy trình thay đổi; thể hiện chúng trong một bức tranh chung. Dùng bức tranh đó để đánh giá tác động, cập nhật cam kết và thông báo nhất quán."},"R1::Use predictive delivery for every workstream":{correct:!1,why:"Ép mọi luồng vào cách dự báo giả định yêu cầu và phụ thuộc sẽ ổn định, nên không phù hợp với phần cần phản hồi thường xuyên. Khi điều kiện thay đổi, kế hoạch cứng tạo làm lại hoặc khiến nhóm né phản hồi của khách hàng."},"R1::Use agile delivery for every workstream regardless of constraints":{correct:!1,why:"Ép mọi luồng chạy lặp lại có thể xung đột với mốc pháp lý, hợp đồng hoặc thiết bị cần kiểm soát trước. Cách này cũng bỏ qua nhu cầu lập kế hoạch dài hạn và làm các phụ thuộc bắt buộc khó quản lý."},"R1::Allow each team to plan independently with no integration":{correct:!1,why:"Kế hoạch tách rời che giấu phụ thuộc, giả định lịch khác nhau và các điểm giao không khả thi. Khi nhóm phát hiện xung đột trong lúc thực hiện, việc sắp xếp lại nguồn lực và mốc bàn giao sẽ tốn kém hơn."},"R1::Delay lifecycle selection until execution is complete":{correct:!1,why:"Vòng đời quyết định cách lập kế hoạch, giao hàng, phản hồi và quản trị; trì hoãn nó khiến nhóm không biết phải cam kết và đo lường ra sao. Các giả định trái ngược sẽ ăn sâu vào kế hoạch trước khi có cơ chế xử lý."},"R1::Copy the plan from a previous project":{correct:!1,why:"Dự án trước có bối cảnh, phụ thuộc, mức bất định và ràng buộc khác nên kế hoạch của nó không phải bằng chứng phù hợp cho dự án hiện tại. Sao chép có thể bỏ sót rủi ro mới và tạo ảo tưởng rằng các mốc đã được kiểm chứng."},"R1::Focus only on schedule and omit governance and benefits":{correct:!1,why:"Lịch đúng hạn không bảo đảm dự án tạo ra lợi ích hoặc tuân thủ quyền quyết định, kiểm soát và phụ thuộc. Bỏ governance làm các thay đổi thiếu chủ sở hữu, còn bỏ benefits khiến nhóm giao đúng thời gian nhưng sai giá trị."},"R2::Clarify requirements and boundaries, then decompose work into manageable components":{correct:!0,why:"Làm rõ yêu cầu và ranh giới trước giúp biết chính xác sản phẩm nào thuộc phạm vi và tiêu chí nào dùng để nghiệm thu. Sau đó phân rã thành thành phần quản lý được giúp ước lượng, giao trách nhiệm và theo dõi mà không biến phạm vi thành danh sách mơ hồ.",exp:"Xác nhận nhu cầu, phần loại trừ và tiêu chí chấp nhận với các bên phù hợp; chỉ khi ranh giới rõ mới phân rã công việc. Kiểm tra mỗi thành phần còn truy nguyên được về yêu cầu và có thể nghiệm thu."},"R2::Assess the request against scope and use the agreed change or backlog process":{correct:!0,why:"Một yêu cầu mới phải được so với mục tiêu và phạm vi hiện tại, rồi đi qua quy trình thay đổi hoặc sắp xếp backlog đã thống nhất. Cách này cho phép nhận giá trị mới mà vẫn thấy rõ tác động đến thời gian, chi phí và cam kết.",exp:"Xác định giá trị, tác động và phụ thuộc của yêu cầu; trình qua đúng quyền phê duyệt hoặc cơ chế ưu tiên. Chỉ cập nhật phạm vi và kế hoạch sau khi quyết định được ghi nhận và truyền đạt."},"R2::Validate scope understanding and acceptance criteria with relevant stakeholders":{correct:!0,why:"Xác nhận với người tạo, sử dụng và nghiệm thu sản phẩm giúp phát hiện cách hiểu khác nhau trước khi nhóm xây dựng. Tiêu chí chấp nhận rõ biến phạm vi thành kết quả có thể kiểm chứng thay vì kỳ vọng ngầm.",exp:"Đưa các bên xem lại sản phẩm, phần loại trừ và điều kiện chấp nhận bằng ví dụ cụ thể. Ghi lại điểm thống nhất, xử lý khoảng trống và dùng tiêu chí đó để đánh giá đầu ra."},"R2::Start the easiest work before defining boundaries":{correct:!1,why:"Làm việc dễ trước khi biết ranh giới có thể tạo ra đầu ra không thuộc mục tiêu hoặc dựa trên yêu cầu sai. Khi làm rõ phạm vi sau đó, phần đã làm có thể phải bỏ hoặc xây lại."},"R2::Accept every valuable-sounding request immediately":{correct:!1,why:"Giá trị được cảm nhận không đủ để tự động thêm yêu cầu vào phạm vi; cần xem xét mục tiêu, tác động, phụ thuộc và quyền phê duyệt. Nhận tất cả ngay sẽ tạo scope creep và làm loãng ưu tiên."},"R2::Freeze scope so no approved change is possible":{correct:!1,why:"Đóng băng tuyệt đối coi mọi thay đổi hợp lệ là mối đe dọa, trong khi bối cảnh và nhu cầu có thể thay đổi. Cách đúng là kiểm soát thay đổi có đánh giá tác động, không phải từ chối cả thay đổi có lợi."},"R2::Let developers infer missing acceptance criteria":{correct:!1,why:"Để lập trình viên tự đoán tiêu chí chấp nhận chuyển quyết định sản phẩm thành giả định cá nhân. Các bên có thể không công nhận đầu ra, còn lỗi chỉ lộ ra ở kiểm thử hoặc bàn giao."},"R2::Use schedule variance to define product scope":{correct:!1,why:"Chênh lệch lịch cho biết tiến độ, không nói sản phẩm cần chứa gì hoặc đạt điều kiện nào. Dùng nó để định nghĩa phạm vi sẽ khiến nhóm cắt hoặc thêm nội dung mà không có căn cứ giá trị và nghiệm thu."},"R2::Decompose work before understanding the deliverable":{correct:!1,why:"Phân rã trước khi hiểu sản phẩm tạo ra các gói việc dựa trên phỏng đoán và có thể bỏ sót yêu cầu. Khi làm rõ deliverable, cấu trúc đã lập sẽ phải sửa, kéo theo ước lượng và trách nhiệm."},"R3::Prioritize by value, risk, dependencies, and time to benefit":{correct:!0,why:"Ưu tiên cần cân nhắc lợi ích dự kiến cùng rủi ro, thứ tự phụ thuộc và thời điểm lợi ích xuất hiện. Cách nhìn nhiều chiều giúp chọn việc mở khóa giá trị sớm mà không bỏ qua điều kiện tuân thủ hoặc rủi ro lớn.",exp:"Đánh giá từng hạng mục theo lợi ích, rủi ro, phụ thuộc và thời gian tạo giá trị; sau đó xếp thứ tự có lý do. Theo dõi kết quả thực tế để điều chỉnh ưu tiên khi bằng chứng thay đổi."},"R3::Deliver a usable value slice early and measure the outcome":{correct:!0,why:"Giao một phần có thể sử dụng sớm tạo cơ hội kiểm chứng giả định với người dùng thay vì đợi toàn bộ giải pháp. Đo kết quả cho biết phần đó có thật sự cải thiện outcome và nên đầu tư tiếp hay không.",exp:"Chọn lát cắt nhỏ nhưng có ích, xác định chỉ số kết quả và đưa đến người dùng phù hợp. So sánh kết quả với mục tiêu, học từ phản hồi rồi điều chỉnh phần tiếp theo."},"R3::Revisit priorities with stakeholders using benefit evidence and feedback":{correct:!0,why:"Ưu tiên ban đầu là giả định; bằng chứng lợi ích và phản hồi thực tế có thể cho thấy hạng mục khác đáng làm trước. Rà soát cùng stakeholder giữ quyết định gắn với giá trị hiện tại thay vì chức danh hoặc thói quen.",exp:"Thu thập dữ liệu sử dụng, lợi ích và phản hồi; trình bày tác động của từng lựa chọn. Cùng stakeholder sắp xếp lại backlog, ghi rõ lý do và kiểm tra lại sau khi giao hàng."},"R3::Prioritize the item with the largest effort estimate":{correct:!1,why:"Ước lượng nỗ lực cho biết chi phí tương đối, không cho biết lợi ích hay tính cấp thiết. Chọn việc lớn nhất có thể tiêu tốn năng lực vào hạng mục ít giá trị và trì hoãn điều thực sự mở khóa lợi ích."},"R3::Choose only the most popular request":{correct:!1,why:"Mức phổ biến phản ánh số người lên tiếng chứ không chứng minh tác động, doanh thu, rủi ro hoặc phụ thuộc. Chọn theo sự ưa thích có thể bỏ qua enabler quan trọng hoặc yêu cầu tuân thủ ít được ủng hộ."},"R3::Maximize the number of completed features":{correct:!1,why:"Nhiều tính năng hoàn thành là output, không phải bằng chứng người dùng đạt kết quả tốt hơn. Tối đa hóa số lượng dễ tạo phần dư thừa và làm nhóm bỏ qua chất lượng, adoption hoặc lợi ích đo được."},"R3::Order work by stakeholder title":{correct:!1,why:"Chức danh không phải tiêu chí đo giá trị hay rủi ro của hạng mục. Cho người có chức vụ cao quyền ưu tiên mặc định có thể làm méo backlog và bỏ qua nhu cầu của người sử dụng."},"R3::Delay all value until the complete solution is finished":{correct:!1,why:"Chờ toàn bộ giải pháp mới tạo giá trị làm mất cơ hội học sớm và trì hoãn lợi ích có thể giao từng phần. Nếu giả định sai, nhóm sẽ phát hiện sau khi đã đầu tư hầu hết chi phí."},"R3::Treat velocity as the business benefit":{correct:!1,why:"Velocity đo lượng công việc nhóm hoàn thành theo cách riêng, không đo doanh thu, adoption, chất lượng hay outcome của khách hàng. Đồng nhất hai thứ khuyến khích tối ưu điểm số và che giấu việc sản phẩm không tạo giá trị."},"R4::Assess the capability and availability gap, then collaborate on a feasible resource response":{correct:!0,why:"Trước khi cam kết, quản lý dự án cần xác định thiếu kỹ năng nào, thiếu bao lâu và nguồn lực hiện có thực sự rảnh đến đâu. Phối hợp với các bên để chọn đào tạo, ghép cặp, sắp xếp lại hoặc hỗ trợ được phê duyệt giúp giải quyết khoảng cách mà không hứa quá khả năng.",exp:"Đối chiếu yêu cầu công việc với năng lực và lịch sẵn có; lượng hóa tác động của khoảng trống. Cùng chủ sở hữu nguồn lực chọn phương án, cập nhật cam kết và kiểm tra năng lực đã đủ chưa."},"R4::Balance demand with capacity using training, pairing, sequencing, or approved support":{correct:!0,why:"Điều hòa nhu cầu với năng lực có thể dùng đào tạo, ghép người, đổi thứ tự hoặc hỗ trợ được phê duyệt, thay vì chỉ yêu cầu làm thêm. Các lựa chọn này xử lý cả năng lực và thời điểm, bảo vệ chất lượng và tính khả thi của lịch.",exp:"Xác định việc nào cần kỹ năng khan hiếm và khi nào; so sánh với capacity thực. Đánh giá chi phí, thời gian và rủi ro của từng phương án, rồi lập lịch phù hợp và theo dõi kết quả."},"R4::Update the resource plan and commitments based on realistic availability":{correct:!0,why:"Khi availability thay đổi, kế hoạch nguồn lực và cam kết phải phản ánh số giờ, kỹ năng và thời điểm thực tế. Cập nhật sớm giúp stakeholder thấy tác động và cho phép điều chỉnh phạm vi hoặc thứ tự trước khi trễ mốc.",exp:"Xác nhận lịch và năng lực thực với người sở hữu nguồn lực; cập nhật phân bổ, mốc và trách nhiệm. Truyền đạt thay đổi, kiểm tra chênh lệch định kỳ và chỉ cam kết phần capacity có căn cứ."},"R4::Commit the work and expect overtime":{correct:!1,why:"Cam kết trước rồi trông chờ làm thêm biến thiếu năng lực thành rủi ro kiệt sức, lỗi và trễ mốc. Nó không giải quyết kỹ năng khan hiếm, chỉ che giấu việc lịch vượt capacity."},"R4::Remove quality criteria that require the missing skill":{correct:!1,why:"Cắt tiêu chí chất lượng để che thiếu kỹ năng làm tăng lỗi và chuyển chi phí sang vận hành hoặc khách hàng. Phương án phải xử lý khoảng trống năng lực, không hy sinh điều kiện làm sản phẩm chấp nhận được."},"R4::Assume all resources with the same title are interchangeable":{correct:!1,why:"Cùng chức danh không có nghĩa cùng kinh nghiệm, chứng chỉ, bối cảnh hay khả năng làm nhiệm vụ cụ thể. Giả định thay thế được có thể phân người sai và phát hiện thiếu kỹ năng khi công việc đã bị chặn."},"R4::Add people without considering onboarding cost":{correct:!1,why:"Thêm người không tính thời gian hướng dẫn, phối hợp và ảnh hưởng đến năng suất có thể làm lịch chậm hơn, đặc biệt với công việc phức tạp. Tăng đầu người không tự động bù được kỹ năng khan hiếm."},"R4::Hide the shortage until a milestone is missed":{correct:!1,why:"Che thiếu hụt tước cơ hội tìm đào tạo, hỗ trợ hoặc điều chỉnh phạm vi khi còn thời gian. Đợi đến khi trễ mốc biến vấn đề có thể quản thành khủng hoảng và làm mất niềm tin."},"R4::Allocate the same specialist full-time to multiple projects":{correct:!1,why:"Phân một người toàn thời gian cho nhiều dự án đồng thời tạo cam kết không thể đáp ứng và chuyển chi phí sang chờ đợi, chuyển ngữ cảnh. Chuyên gia sẽ không thực sự sẵn sàng cho bất kỳ mốc nào."},"R5::Match the procurement and contract strategy to scope certainty and risk allocation":{correct:!0,why:"Loại hợp đồng và chiến lược mua sắm phải phù hợp độ rõ của phạm vi, mức bất định và bên nào có thể kiểm soát rủi ro. Ghép đúng giúp phân bổ chi phí vượt dự toán minh bạch và bảo vệ giá trị thay vì chọn một mẫu hợp đồng theo thói quen.",exp:"Xác định phạm vi, make-or-buy, khả năng dự báo và rủi ro mà mỗi bên có thể quản; sau đó chọn chiến lược và điều khoản tương ứng. Đánh giá lại khi phạm vi hoặc rủi ro thay đổi trước khi cam kết."},"R5::Use objective criteria to evaluate options and follow the approved source-selection process":{correct:!0,why:"Tiêu chí khách quan cho phép so sánh năng lực, chất lượng, chi phí toàn vòng đời và rủi ro thay vì dựa vào ấn tượng hoặc giá niêm yết. Tuân thủ quy trình lựa chọn bảo đảm quyết định có bằng chứng, công bằng và có thể kiểm tra.",exp:"Xác định tiêu chí trọng số theo mục tiêu và rủi ro; thu thập bằng chứng giống nhau từ các nhà cung cấp. Chấm điểm, ghi lý do và hoàn tất các bước phê duyệt trước khi trao hợp đồng."},"R5::Review contract obligations and performance, then apply the agreed corrective process":{correct:!0,why:"Khi nhà cung cấp trượt mức dịch vụ, quản lý dự án cần đối chiếu nghĩa vụ và bằng chứng hiệu suất trước khi hành động. Áp dụng biện pháp khắc phục đã thỏa thuận giữ quyền lợi hợp đồng, trách nhiệm và lộ trình cải thiện rõ ràng.",exp:"Kiểm tra điều khoản, số liệu vi phạm và nguyên nhân; trao đổi với nhà cung cấp về kế hoạch phục hồi. Kích hoạt điều khoản khắc phục hoặc escalation phù hợp, đặt thời hạn và xác minh hiệu suất sau đó."},"R5::Always choose the lowest bid":{correct:!1,why:"Giá chào thấp nhất không cho biết tổng chi phí, chất lượng, năng lực hoặc rủi ro giao hàng. Chọn chỉ theo giá có thể tạo chi phí vượt mức và thất bại hợp đồng lớn hơn khoản tiết kiệm ban đầu."},"R5::Use a verbal agreement to save time":{correct:!1,why:"Thỏa thuận miệng không ghi rõ phạm vi, giá, trách nhiệm, tiêu chí nghiệm thu hay cách xử lý tranh chấp. Tiết kiệm thời gian lúc đầu làm mất khả năng truy cứu và tạo bất đồng khi thực hiện."},"R5::Select fixed price when scope is highly uncertain without safeguards":{correct:!1,why:"Giá cố định với phạm vi chưa rõ khuyến khích tranh chấp thay đổi, dự phòng quá mức hoặc chất lượng bị cắt giảm. Nếu chọn hình thức này, phải có phạm vi đủ xác định và cơ chế quản lý thay đổi; option đã bỏ qua điều đó."},"R5::Change supplier obligations outside the contract":{correct:!1,why:"Tự ý đổi nghĩa vụ ngoài hợp đồng phá vỡ quyền phê duyệt, khả năng truy nguyên và cân bằng rủi ro đã thỏa thuận. Nó có thể tạo khiếu nại hoặc cam kết mà ngân sách và pháp lý chưa chấp thuận."},"R5::Ignore make-or-buy analysis":{correct:!1,why:"Bỏ qua make-or-buy khiến dự án không so sánh chi phí, năng lực, thời gian và rủi ro giữa tự làm với mua ngoài. Quyết định thiếu phân tích có thể khóa vào nguồn cung không phù hợp."},"R5::Accept repeated misses to preserve the relationship":{correct:!1,why:"Chấp nhận nhà cung cấp trượt liên tục để giữ quan hệ làm suy yếu mức dịch vụ và tín hiệu trách nhiệm. Không có biện pháp khắc phục, dự án phải gánh chậm trễ và rủi ro mà hợp đồng được lập để kiểm soát."},"R6::Use the appropriate approved reserve and maintain transparent cost records":{correct:!0,why:"Khi rủi ro đã xảy ra, cần dùng đúng loại khoản dự phòng đã được phê duyệt và ghi nhận chi phí minh bạch để giữ đường cơ sở và dự báo đáng tin. Cách này tài trợ cho ứng phó mà không che giấu nguyên nhân hoặc chuyển chi phí sai chỗ.",exp:"Xác nhận sự kiện, phương án ứng phó và quyền sử dụng contingency hay management reserve; xin phê duyệt nếu cần. Ghi actual, điều chỉnh dự báo và báo cáo tác động cùng quyết định tài chính."},"R6::Validate progress and cost data before forecasting and choosing corrective action":{correct:!0,why:"Dự báo chỉ có ý nghĩa khi dữ liệu tiến độ và chi phí phản ánh thực tế; nếu thiếu một trong hai, variance có thể bị hiểu sai. Kiểm chứng dữ liệu trước giúp chọn biện pháp đúng nguyên nhân thay vì cắt giảm hoặc bơm tiền theo con số lỗi.",exp:"Đối chiếu tiến độ thực, chi phí phát sinh và bằng chứng hoàn thành; làm rõ sai lệch dữ liệu. Sau đó tính lại dự báo, phân tích nguyên nhân và chọn hành động có tác động đo được."},"R6::Update the forecast using current evidence and follow financial governance":{correct:!0,why:"Dự báo phải dùng bằng chứng mới nhất về hiệu suất, rủi ro và cam kết, không giữ nguyên con số đã lỗi thời. Tuân thủ governance bảo đảm thay đổi ngân sách có người phê duyệt, dấu vết và thông báo đúng bên.",exp:"Thu thập actuals, xu hướng và tác động rủi ro; cập nhật estimate at completion hoặc dự báo tương ứng. Trình theo ngưỡng phê duyệt, ghi quyết định và theo dõi chênh lệch sau điều chỉnh."},"R6::Use management reserve without approval for any overrun":{correct:!1,why:"Tự ý dùng management reserve phá vỡ quyền phê duyệt và che khuất lý do vượt chi phí. Khoản dự phòng không phải nguồn tiền tùy ý; phải xác định loại sự kiện và thực hiện governance tương ứng."},"R6::Move costs to operations to protect the baseline":{correct:!1,why:"Chuyển chi phí sang vận hành chỉ làm đường cơ sở dự án trông đẹp hơn, không làm chi phí biến mất. Cách này phá tính minh bạch, làm sai quyết định ngân sách và đẩy gánh nặng sang bộ phận khác."},"R6::Hide variance until the next funding cycle":{correct:!1,why:"Giấu variance trì hoãn phản ứng khi còn có thể sửa và khiến stakeholder ra quyết định dựa trên thông tin sai. Đến kỳ cấp vốn sau, phạm vi sai lệch và chi phí phục hồi thường đã lớn hơn."},"R6::Treat spent budget as equivalent to earned progress":{correct:!1,why:"Tiền đã chi chỉ phản ánh outlay, không chứng minh khối lượng đạt tiêu chí hay giá trị đã tạo. Đồng nhất hai chỉ số làm dự báo hiệu suất sai và có thể che việc chi phí tăng nhưng tiến độ không đạt."},"R6::Remove contingency to improve the forecast":{correct:!1,why:"Xóa contingency chỉ làm con số dự báo thấp hơn trên giấy, đồng thời bỏ nguồn ứng phó rủi ro còn tồn tại. Nó không cải thiện hiệu suất thật và làm dự án dễ bị động khi sự kiện xảy ra."},"R6::Approve funding beyond the project manager’s authority":{correct:!1,why:"Phê duyệt vượt thẩm quyền khiến cam kết tài chính không hợp lệ và không có chủ sở hữu governance phù hợp. Quyết định phải được chuyển đúng cấp cùng phân tích tác động, không thể hợp thức hóa bằng sự khẩn cấp."},"R7::Analyze the cause and build quality checks earlier into the workflow":{correct:!0,why:"Nếu lỗi chỉ được phát hiện ở cuối, cần tìm nguyên nhân và đưa kiểm tra vào điểm tạo ra lỗi thay vì chỉ tăng bắt lỗi. Kiểm tra sớm giảm chi phí sửa, cung cấp phản hồi nhanh và ngăn cùng một lỗi đi tiếp qua nhiều bước.",exp:"Phân loại lỗi, truy nguyên nguyên nhân và xác định điểm kiểm soát gần nguồn phát sinh. Đưa tiêu chí hoặc kiểm tra tự động vào quy trình, rồi đo tỷ lệ lỗi lặp lại sau thay đổi."},"R7::Clarify measurable acceptance criteria and agree how evidence will be produced":{correct:!0,why:"Tiêu chí chấp nhận đo được biến khái niệm chất lượng thành điều kiện có thể kiểm tra và thống nhất. Quy định trước bằng chứng cần tạo giúp nhóm và người nghiệm thu không tranh luận theo cảm nhận ở cuối chu kỳ.",exp:"Thống nhất hành vi, ngưỡng và dữ liệu chứng minh cho từng tiêu chí; gắn chúng với người tạo và người xác nhận. Kiểm tra bằng chứng trong quá trình thực hiện, xử lý khoảng trống trước khi tuyên bố hoàn tất."},"R7::Use root-cause analysis and implement a preventive process improvement":{correct:!0,why:"Phân tích nguyên nhân gốc giúp thay đổi quy trình tạo ra lỗi, còn cải tiến phòng ngừa làm giảm khả năng lỗi tái diễn. Đây là cách biến một sự cố cụ thể thành năng lực chất lượng bền vững.",exp:"Thu thập dữ kiện, phân biệt triệu chứng với nguyên nhân và kiểm chứng giả thuyết. Thực hiện cải tiến có chủ sở hữu, đo kết quả và chuẩn hóa khi bằng chứng cho thấy lỗi giảm."},"R7::Add only more inspection at the end":{correct:!1,why:"Tăng kiểm tra cuối chỉ phát hiện lỗi muộn, sau khi chi phí làm lại đã phát sinh, và không ngăn lỗi tái diễn. Nếu không sửa nơi tạo lỗi, số người kiểm tra nhiều hơn chỉ tạo hàng đợi và chi phí."},"R7::Accept defects when delivery velocity is high":{correct:!1,why:"Tốc độ giao hàng không bù cho lỗi làm giảm an toàn, chất lượng hoặc giá trị của sản phẩm. Chấp nhận lỗi theo một chỉ số duy nhất khiến nợ chất lượng tích tụ và cuối cùng làm chậm delivery."},"R7::Reduce customer reviews to avoid finding issues":{correct:!1,why:"Giảm review chỉ làm mất kênh phát hiện sớm các vấn đề người dùng quan tâm; nó không làm sản phẩm tốt hơn. Lỗi sẽ xuất hiện muộn hơn, khi sửa đã tốn kém và niềm tin giảm."},"R7::Correct each defect without examining recurrence":{correct:!1,why:"Sửa từng lỗi riêng lẻ có thể khôi phục đầu ra hiện tại nhưng bỏ qua nguyên nhân chung. Không xem xét recurrence khiến cùng lỗi quay lại và đội phải lặp lại công việc không tạo thêm giá trị."},"R7::Make quality the tester’s responsibility alone":{correct:!1,why:"Chất lượng được tạo trong thiết kế, phát triển và quy trình, không thể giao hết cho người kiểm thử ở cuối. Tách trách nhiệm làm người tạo lỗi thiếu sở hữu và tester trở thành nút thắt."},"R7::Lower the acceptance threshold after work is complete":{correct:!1,why:"Hạ ngưỡng sau khi làm xong thay đổi định nghĩa hoàn thành để che kết quả không đạt, không loại bỏ lỗi. Nó làm giảm giá trị và tạo tiền lệ rằng tiêu chí có thể bị nới khi gặp khó."},"R8::Assess dependencies and schedule impact before selecting a response":{correct:!0,why:"Chậm trễ ở một hoạt động chỉ có ý nghĩa khi biết nó ảnh hưởng đến phụ thuộc, đường găng và mốc nào. Đánh giá tác động trước giúp chọn phản ứng đúng thay vì nén lịch ở nơi không tạo lợi ích.",exp:"Vẽ lại quan hệ phụ thuộc, xác định đường găng và lượng hóa ảnh hưởng đến mốc; sau đó so sánh các phương án. Chọn phản ứng dựa trên tác động, chi phí và rủi ro, rồi cập nhật lịch có căn cứ."},"R8::Update the schedule with realistic estimates and evaluate response options":{correct:!0,why:"Lịch phải phản ánh ước lượng thực tế sau khi có thông tin mới, đồng thời cho phép so sánh các phương án khắc phục. Cập nhật có kiểm soát tránh việc giữ ngày cũ chỉ để báo cáo đẹp hoặc cam kết một lịch không thể đạt.",exp:"Thu thập ước lượng từ người thực hiện và cập nhật phần việc bị ảnh hưởng; tính lại mốc và dự trữ. Đánh giá fast tracking, crashing hoặc thay đổi phạm vi theo chi phí và rủi ro trước khi phê duyệt."},"R8::Analyze critical path, resource constraints, cost, and risk before compression":{correct:!0,why:"Nén lịch có thể tăng chi phí, tải nguồn lực, phụ thuộc và rủi ro làm lại, nên phải xem toàn bộ hệ quả. Phân tích các yếu tố này giúp biết nén ở đâu thực sự rút ngắn thời gian mà vẫn bảo vệ chất lượng.",exp:"Xác định hoạt động trên đường găng, nguồn lực giới hạn và tác động chi phí; đánh giá rủi ro của từng phương án. Chỉ chọn nén khi lợi ích mốc lớn hơn chi phí và có kế hoạch kiểm soát hậu quả."},"R8::Crash all downstream work immediately":{correct:!1,why:"Đổ thêm nguồn lực vào mọi việc phía sau vừa tốn chi phí vừa có thể làm tăng phối hợp mà không rút ngắn đường găng. Hành động ngay không có phân tích có thể tạo làm lại và vẫn bỏ lỡ nguyên nhân chậm."},"R8::Hide the delay until it becomes certain":{correct:!1,why:"Giấu chậm trễ làm mất thời gian chuẩn bị phương án và khiến stakeholder không thể điều chỉnh quyết định liên quan. Khi chắc chắn rồi, cửa sổ phục hồi có thể đã mất và tác động lan sang nhiều mốc."},"R8::Remove a mandatory milestone":{correct:!1,why:"Xóa mốc bắt buộc để làm lịch trông tốt hơn có thể vi phạm pháp lý, chất lượng hoặc điều kiện bàn giao. Nó không xử lý phụ thuộc và chỉ che chậm trễ bằng cách bỏ tiêu chí kiểm soát."},"R8::Add resources to every activity":{correct:!1,why:"Thêm người vào mọi hoạt động không xét đường găng, kỹ năng và giới hạn phối hợp làm chi phí tăng mà không chắc lịch ngắn hơn. Một số công việc còn chậm hơn vì phải hướng dẫn và đồng bộ nhiều người."},"R8::Shorten estimates without team input":{correct:!1,why:"Rút ngắn ước lượng trên giấy mà không có người thực hiện tham gia không tạo thêm capacity hay loại bỏ phụ thuộc. Cam kết thiếu căn cứ sẽ dẫn đến trễ, làm thêm giờ và mất độ tin cậy của lịch."},"R8::Report percent complete without dependency analysis":{correct:!1,why:"Phần trăm hoàn thành không cho biết công việc còn lại có nằm trên đường găng hay đang chặn nhóm khác. Báo cáo chỉ số này mà không đọc phụ thuộc có thể bỏ sót rủi ro mốc dù con số vẫn tăng."},"R9::Use balanced delivery, quality, risk, and outcome measures to explain true status":{correct:!0,why:"Trạng thái đáng tin cần kết hợp tiến độ giao hàng với chất lượng, rủi ro và kết quả, vì một chỉ số đẹp có thể che vấn đề ở chiều khác. Bức tranh cân bằng giúp governance hiểu tình hình thật và chọn quyết định phù hợp.",exp:"Thu thập các chỉ số phản ánh đầu ra, lỗi, rủi ro và outcome; kiểm tra xu hướng thay vì nhìn một con số. Giải thích mối liên hệ và đưa ra quyết định cần hỗ trợ cùng tác động dự kiến."},"R9::Validate data and present trends, variances, implications, and decisions needed":{correct:!0,why:"Kiểm chứng dữ liệu trước khi báo cáo bảo vệ quyết định khỏi số liệu thiếu hoặc sai. Trình bày xu hướng, variance và hệ quả chuyển báo cáo từ mô tả sang thông tin có thể hành động.",exp:"Đối chiếu nguồn dữ liệu và kỳ đo, làm rõ sai lệch; sau đó diễn giải xu hướng và nguyên nhân. Nêu lựa chọn, quyết định cần xin và hậu quả nếu không hành động, rồi theo dõi kết quả."},"R9::Tailor status artifacts while preserving transparent evidence and context":{correct:!0,why:"Đối tượng khác nhau cần mức chi tiết và định dạng khác nhau, nhưng việc điều chỉnh không được cắt mất bằng chứng hoặc bối cảnh quan trọng. Báo cáo phù hợp người đọc mà vẫn minh bạch giúp họ hiểu đúng cùng một thực trạng.",exp:"Xác định quyết định mỗi audience cần và chọn biểu mẫu tương ứng; giữ liên kết tới dữ liệu nguồn, giả định và giới hạn. Kiểm tra bản rút gọn không làm thay đổi ý nghĩa trước khi phát hành."},"R9::Report green using the most favorable metric":{correct:!1,why:"Chọn chỉ số có lợi để báo xanh tạo ấn tượng sai và có thể che lỗi, rủi ro hoặc outcome kém. Governance sẽ phân bổ nguồn lực dựa trên trạng thái giả và phát hiện vấn đề muộn."},"R9::Stop reporting any metric that creates concern":{correct:!1,why:"Ngừng báo chỉ số bất lợi không làm vấn đề biến mất mà chỉ xóa tín hiệu cần được xử lý. Thiếu dữ liệu xấu phá minh bạch và khiến quyết định không thể cân bằng."},"R9::Present raw data without interpretation":{correct:!1,why:"Dữ liệu thô không tự nói biến động có ý nghĩa gì, ảnh hưởng ra sao hoặc cần quyết định nào. Người đọc có thể hiểu khác nhau và bỏ lỡ hành động cần thiết."},"R9::Use velocity as a cross-team productivity target":{correct:!1,why:"Velocity phụ thuộc cách ước lượng và bối cảnh từng nhóm nên không thể dùng công bằng để so sánh hoặc ép năng suất liên nhóm. Đặt mục tiêu như vậy khuyến khích thổi phồng điểm, hy sinh chất lượng và phá khả năng dự báo."},"R9::Delay bad news until a recovery plan is certain":{correct:!1,why:"Chờ có kế hoạch phục hồi chắc chắn mới báo tin xấu làm mất thời gian để stakeholder hỗ trợ hoặc điều chỉnh phạm vi. Minh bạch sớm cho phép cùng phân tích và giảm tác động trước khi tình hình tệ hơn."},"R9::Replace evidence with subjective confidence":{correct:!1,why:"Sự tự tin của nhóm là tín hiệu hữu ích nhưng không thay thế dữ liệu về tiến độ, chất lượng, rủi ro và outcome. Dựa vào cảm nhận có thể đánh giá quá lạc quan và bỏ qua bằng chứng ngược chiều."},"R10::Verify transition readiness and complete agreed closure activities":{correct:!0,why:"Khách hàng chấp nhận hoặc phát triển đã dừng chưa đủ để đóng dự án; vận hành phải sẵn sàng nhận sản phẩm, tài liệu, hỗ trợ và trách nhiệm. Kiểm tra readiness rồi hoàn tất các hoạt động đã thống nhất giúp tránh chuyển việc còn dang dở sang vận hành.",exp:"Rà soát tiêu chí bàn giao, đào tạo, hỗ trợ, hồ sơ và người sở hữu vận hành; xử lý khoảng trống trước khi đóng. Sau khi có bằng chứng sẵn sàng, hoàn tất acceptance, lưu trữ và các bước kết thúc chính thức."},"R10::Close contracts, archive records, capture lessons, and obtain formal acceptance as applicable":{correct:!0,why:"Đóng hợp đồng và lưu hồ sơ bảo vệ nghĩa vụ pháp lý, còn bài học giúp tổ chức cải thiện dự án sau. Nghiệm thu chính thức tạo bằng chứng rằng đầu ra và điều kiện kết thúc đã được người có thẩm quyền xác nhận.",exp:"Kiểm tra deliverable, nghĩa vụ nhà cung cấp, hồ sơ và bài học; lấy xác nhận nghiệm thu phù hợp với loại dự án. Hoàn tất thanh toán, lưu trữ và thông báo đóng sau khi mọi trách nhiệm đã được xử lý."},"R10::Confirm operational ownership, open actions, and benefit-transition responsibilities":{correct:!0,why:"Chuyển sang vận hành cần một người sở hữu rõ, danh sách hành động còn mở và trách nhiệm theo dõi lợi ích sau dự án. Nếu không, sản phẩm có thể được bàn giao nhưng sự cố, quyết định còn lại và lợi ích không ai quản.",exp:"Xác nhận nhóm vận hành nhận gì, ai xử lý từng hành động mở và ai đo lợi ích vào thời điểm nào. Ghi các cam kết, thời hạn và cơ chế báo cáo rồi chỉ giải phóng đội dự án khi ownership rõ."},"R10::Close as soon as development stops":{correct:!1,why:"Dừng phát triển chỉ nói về hoạt động xây dựng, không chứng minh chuyển giao, nghiệm thu, hợp đồng hay vận hành đã sẵn sàng. Đóng sớm dễ để lại việc mở và làm người dùng nhận một sản phẩm không có hỗ trợ."},"R10::Transfer unresolved actions informally and release everyone":{correct:!1,why:"Bàn giao không chính thức không có người chịu trách nhiệm, thời hạn hoặc bằng chứng tiếp nhận nên việc mở dễ bị quên. Giải phóng đội trước khi xác nhận ownership khiến vận hành phải tự tìm hiểu và khắc phục trong tình trạng bị động."},"R10::Skip lessons because the project was canceled":{correct:!1,why:"Dự án bị hủy vẫn chứa thông tin về giả định, rủi ro và quyết định cần tránh lặp lại. Bỏ qua bài học làm tổ chức mất cơ hội cải thiện và có thể tái diễn cùng nguyên nhân ở dự án sau."},"R10::Keep contracts open after final payment":{correct:!1,why:"Thanh toán cuối không tự động hoàn tất nghĩa vụ, bảo hành, tranh chấp hoặc hồ sơ hợp đồng. Để hợp đồng mở không có lý do làm mờ trách nhiệm và khiến dự án không thể kết thúc minh bạch."},"R10::Assume product acceptance proves operational readiness":{correct:!1,why:"Người dùng chấp nhận sản phẩm chỉ xác nhận một phần tiêu chí đầu ra, không chứng minh đào tạo, hỗ trợ, giám sát và quy trình vận hành đã sẵn sàng. Giả định này có thể gây gián đoạn ngay sau bàn giao."},"R10::Delete project records to reduce storage":{correct:!1,why:"Xóa hồ sơ làm mất bằng chứng quyết định, hợp đồng, nghiệm thu và bài học cần cho audit hoặc vận hành. Tiết kiệm lưu trữ không bù được rủi ro pháp lý và mất khả năng truy nguyên."}},R={"B1::Follow defined decision rights and escalate through the appropriate governance path":{correct:!0,why:"Quyền quyết định xác định ai được phê duyệt theo ngưỡng nào; đi đúng đường quản trị giữ trách nhiệm và dấu vết rõ ràng. Vấn đề vượt thẩm quyền được đưa đến đúng cấp thay vì quyết định tùy tiện.",exp:"Xác định ngưỡng, quyền hạn và bằng chứng cần có; chuẩn bị hồ sơ tác động. Nếu vượt quyền, chuyển cấp, ghi quyết định và thông báo cho các bên bị ảnh hưởng. Bẫy là tự phê duyệt khi vượt quyền hoặc chỉ báo cáo mà không chuyển cấp."},"B1::Clarify roles, thresholds, evidence, and escalation before the next decision":{correct:!0,why:"Làm rõ vai trò, ngưỡng và bằng chứng trước quyết định ngăn việc dựa vào chức danh hoặc áp lực thời gian. Mọi người biết ai chịu trách nhiệm và khi nào phải chuyển cấp.",exp:"Lập ma trận quyền quyết định và tiêu chuẩn bằng chứng, rồi xác nhận với chủ sở hữu. Trước mỗi quyết định, kiểm tra hồ sơ và chuyển cấp khi ngưỡng bị vượt. Bẫy là để chức danh hoặc áp lực thời gian thay cho ngưỡng và bằng chứng."},"B1::Tailor governance to complexity while preserving accountability and transparency":{correct:!0,why:"Governance nên tương xứng với rủi ro và độ phức tạp, nhưng việc điều chỉnh thủ tục không được làm mất người chịu trách nhiệm hay thông tin minh bạch. Nhờ vậy việc đơn giản không bị chặn còn quyết định lớn vẫn được kiểm soát.",exp:"Đánh giá rủi ro, phụ thuộc và số bên liên quan để chọn nhịp và mức kiểm soát. Ghi owner, lý do và bằng chứng để cơ chế nhẹ hơn vẫn có thể kiểm tra. Bẫy là giản lược governance đến thủ tục nặng nề hoặc bỏ owner để làm nhanh."},"B1::Approve the decision because delay is inconvenient":{correct:!1,why:"Sự bất tiện không trao thêm quyền phê duyệt. Duyệt vượt thẩm quyền tạo cam kết không hợp lệ và có thể buộc tổ chức sửa hậu quả sau đó."},"B1::Reject every request above the threshold":{correct:!1,why:"Ngưỡng cao yêu cầu chuyển quyết định lên cấp phù hợp, không phải tự động từ chối. Từ chối cứng nhắc có thể bỏ qua thay đổi tạo giá trị và biến quản trị thành rào cản."},"B1::Let the loudest stakeholder decide":{correct:!1,why:"Mức gây áp lực không phải quyền quyết định hay bằng chứng về giá trị. Cho người nói lớn nhất quyết định bỏ qua vai trò, ngưỡng và lợi ích của các bên khác."},"B1::Create an unofficial path around the steering committee":{correct:!1,why:"Đường tắt không chính thức né cơ quan được giao quyền và làm mất dấu vết phê duyệt. Nó tạo cam kết không rõ trách nhiệm, dù có thể nhanh trong ngắn hạn."},"B1::Escalate every minor operational choice":{correct:!1,why:"Leo thang mọi lựa chọn nhỏ làm quá tải cấp quản trị và tước quyền xử lý của đội. Escalation chỉ cần khi vấn đề vượt ngưỡng, quyền hạn hoặc rủi ro mà vai trò hiện tại có thể quản."},"B1::Treat governance as status reporting only":{correct:!1,why:"Quản trị còn bao gồm quyền quyết định, ngưỡng, hành động và trách nhiệm, không chỉ báo cáo. Chỉ gửi trạng thái khiến rủi ro được nhìn thấy nhưng không có cơ chế xử lý."},"B2::Confirm the obligation with qualified experts and assess impact before acting":{correct:!0,why:"Nghĩa vụ pháp lý cần được xác nhận với chuyên gia có thẩm quyền rồi phân tích tác động lên sản phẩm, lịch và dữ liệu. Trình tự này tránh hiểu sai quy định và tránh hành động vội phải làm lại.",exp:"Xác định điều khoản áp dụng và chủ sở hữu, sau đó đánh giá gap và tác động. Chọn biện pháp đáp ứng, kiểm thử và phê duyệt trước phát hành. Bẫy là phát hành trước rồi sửa hoặc để người không đủ thẩm quyền tự diễn giải."},"B2::Define required evidence, ownership, and verification in the delivery plan":{correct:!0,why:"Compliance đáng tin khi biết bằng chứng nào cần tạo, ai sở hữu và kiểm tra lúc nào. Đưa điều kiện đó vào kế hoạch biến nghĩa vụ thành công việc theo dõi được.",exp:"Chuyển nghĩa vụ thành tiêu chí, hồ sơ và bước kiểm chứng; gán owner. Đặt điểm kiểm tra trong quy trình, lưu bằng chứng và xử lý thiếu sót trước mốc phát hành. Bẫy là chỉ ghi tiêu chí trên giấy hoặc đợi audit cuối mới tìm gap."},"B2::Monitor controls and remediate gaps through the appropriate governance process":{correct:!0,why:"Theo dõi kiểm soát liên tục giúp phát hiện khoảng trống trước khi thành vi phạm; xử lý qua quản trị bảo đảm đúng người phê duyệt. Compliance vì thế không kết thúc ở một lần audit.",exp:"Đo hiệu lực kiểm soát, ghi gap và đánh giá ảnh hưởng; lập kế hoạch khắc phục có hạn. Báo cáo theo ngưỡng, xác nhận bằng chứng và cập nhật kiểm soát khi bối cảnh đổi. Bẫy là coi compliance là kiểm tra một lần, không theo dõi kiểm soát và gap mới."},"B2::Release first and fix compliance later":{correct:!1,why:"Phát hành trước khi chứng minh nghĩa vụ được đáp ứng có thể gây vi phạm, phạt hoặc thu hồi. Sửa sau tốn kém hơn vì dữ liệu và người dùng đã chịu tác động."},"B2::Let each developer interpret the regulation independently":{correct:!1,why:"Để từng lập trình viên tự diễn giải tạo cách hiểu không nhất quán và không có owner pháp lý. Một sai khác nhỏ có thể khiến kiểm soát không đủ bảo vệ tổ chức."},"B2::Remove functionality without impact analysis":{correct:!1,why:"Cắt tính năng có thể phá giá trị hoặc phụ thuộc khác mà chưa chứng minh xử lý được nghĩa vụ. Cần đánh giá gap và tác động trước khi chọn biện pháp."},"B2::Treat compliance as a one-time final audit":{correct:!1,why:"Đợi audit cuối phát hiện vấn đề sau khi thiết kế đã khóa nhiều quyết định. Nghĩa vụ cần được theo dõi và kiểm chứng trong suốt quá trình giao hàng."},"B2::Hide the gap to protect the launch date":{correct:!1,why:"Che khoảng trống chỉ bảo vệ ngày phát hành trên giấy và tước cơ hội khắc phục sớm. Khi bị phát hiện, chi phí dừng, sửa hoặc phạt sẽ lớn hơn."},"B2::Ask the customer to accept legal risk informally":{correct:!1,why:"Chấp nhận rủi ro pháp lý không chính thức không thay thế nghĩa vụ của tổ chức và không tạo hồ sơ có thẩm quyền. Nó chuyển hậu quả cho khách hàng mà không có đánh giá hay phê duyệt hợp lệ."},"B3::Record the request, assess impact, and route it through the agreed decision process":{correct:!0,why:"Ghi nhận tạo dấu vết, còn phân tích tác động cho biết thay đổi ảnh hưởng phạm vi, lịch, chi phí và lợi ích ra sao. Đưa hồ sơ qua quy trình giúp quyết định có owner và các bên hiểu cam kết mới.",exp:"Tiếp nhận, đánh giá tác động và xác định quyền quyết định. Trình đúng cấp, ghi kết quả rồi cập nhật kế hoạch và truyền thông trước triển khai. Bẫy là bắt đầu vì requester cấp cao hoặc phê duyệt trước khi biết impact."},"B3::Implement only after authorization, then update affected plans and communicate":{correct:!0,why:"Ủy quyền là điều kiện để biến đề xuất thành cam kết; làm trước có thể tạo công việc không được phê duyệt. Sau khi duyệt, cập nhật kế hoạch và thông báo giúp đội làm theo phiên bản mới.",exp:"Xác nhận quyết định và điều kiện phê duyệt, rồi lập kế hoạch thực hiện. Cập nhật phạm vi, lịch, ngân sách và backlog trước khi bắt đầu. Bẫy là chỉ cập nhật lịch hoặc làm shadow work sau khi duyệt."},"B3::Use the tailored change or backlog process while preserving traceability":{correct:!0,why:"Quy trình có thể điều chỉnh theo cách giao hàng nhưng phải giữ liên kết từ yêu cầu đến quyết định, thực hiện và kết quả. Truy nguyên đầy đủ giúp giải thích vì sao thay đổi được nhận, hoãn hoặc từ chối.",exp:"Chọn quy trình thay đổi hoặc backlog phù hợp, ghi người yêu cầu và tác động. Giữ lịch sử ưu tiên, phê duyệt và phiên bản để mọi bên kiểm tra được đường đi. Bẫy là cho mọi stakeholder sửa backlog trực tiếp, làm mất quyền sở hữu và traceability."},"B3::Start work because the requester is senior":{correct:!1,why:"Chức vụ không thay thế phê duyệt hay phân tích tác động. Bắt đầu sớm có thể tiêu ngân sách và làm sai đường cơ sở trước khi tổ chức quyết định."},"B3::Reject all changes because the baseline is fixed":{correct:!1,why:"Đường cơ sở là mốc kiểm soát, không phải lệnh cấm mọi thay đổi hợp lệ. Thay đổi cần được đánh giá và phê duyệt, không bị từ chối tuyệt đối."},"B3::Ask the team to work unofficially":{correct:!1,why:"Làm không chính thức tạo đầu ra không có quyền hạn, ngân sách hoặc truy nguyên, rồi có thể phải bỏ. Nó cũng làm mờ trách nhiệm và né quy trình kiểm soát."},"B3::Approve before impact analysis":{correct:!1,why:"Phê duyệt khi chưa biết tác động có thể làm lịch, chi phí hoặc nghĩa vụ vượt khả năng dự án. Quyết định thiếu dữ kiện dễ dẫn đến làm lại."},"B3::Update only the schedule after approval":{correct:!1,why:"Thay đổi thường ảnh hưởng phạm vi, chi phí, nguồn lực, rủi ro và truyền thông; chỉ sửa lịch làm các kế hoạch khác mâu thuẫn. Đội có thể thực hiện theo cam kết cũ."},"B3::Let every stakeholder reprioritize the backlog directly":{correct:!1,why:"Cho mọi stakeholder sửa ưu tiên trực tiếp phá quyền sở hữu sản phẩm và tạo backlog không nhất quán. Phản hồi cần được đánh giá qua vai trò và quy trình đã thống nhất."},"B4::Make the issue visible, assess impact, assign ownership, and coordinate removal":{correct:!0,why:"Issue đã xảy ra cần được ghi rõ, đánh giá tác động và giao owner có quyền điều phối gỡ vật cản. Chuỗi này biến outage thành công việc có hạn thay vì thông tin thụ động.",exp:"Đăng ký issue, xác định đội và mốc bị ảnh hưởng, rồi gán owner cùng hạn xử lý. Theo dõi hành động và xác nhận bằng chứng rằng luồng đã thông. Bẫy là ghi outage như risk tương lai hoặc đóng khi mới có workaround."},"B4::Prioritize active impediments by impact and urgency, then track resolution":{correct:!0,why:"Xếp impediment theo tác động và khẩn cấp giúp xử lý thứ đang chặn nhiều giá trị nhất. Theo dõi đến khi giải quyết ngăn việc chỉ ghi nhận mà không phục hồi dòng công việc.",exp:"Đánh giá phạm vi ảnh hưởng và phụ thuộc, chọn thứ tự xử lý. Gán owner, đặt mốc kiểm tra và cập nhật cho đến khi có bằng chứng hoàn tất. Bẫy là escalation ngay không owner/impact hoặc tăng commitment khi đội bị chặn."},"B4::Address the root constraint and confirm that flow has actually resumed":{correct:!0,why:"Workaround chỉ có thể làm nhóm chạy tạm, còn nguyên nhân gốc vẫn khiến issue quay lại. Gỡ ràng buộc và quan sát dữ liệu flow xác nhận biện pháp thật sự hiệu quả.",exp:"Truy tìm ràng buộc tạo issue và thực hiện hành động loại bỏ hoặc giảm nó. Theo dõi thời gian chờ và đầu ra sau xử lý, chỉ đóng khi hoạt động ổn định. Bẫy là sửa symptom, không gỡ root constraint, rồi tuyên bố flow đã hồi phục."},"B4::Record the active outage only as a future risk":{correct:!1,why:"Outage đang xảy ra là issue cần hành động ngay, không phải rủi ro tương lai chỉ để theo dõi. Ghi sai loại làm thiếu owner và để nhóm tiếp tục bị chặn."},"B4::Wait for the retrospective to act":{correct:!1,why:"Retrospective giúp học sau sự kiện nhưng không thay thế xử lý blocker hôm nay. Chờ đến đó kéo dài gián đoạn và có thể làm trễ mốc."},"B4::Increase commitment while the team is blocked":{correct:!1,why:"Tăng cam kết khi đầu vào vẫn bị chặn làm thêm công việc dở dang và che capacity thực. Nó không gỡ impediment mà còn tăng áp lực lên chất lượng."},"B4::Escalate without first identifying ownership and impact":{correct:!1,why:"Escalation thiếu owner, mức ảnh hưởng và yêu cầu cụ thể khiến cấp trên khó hành động và vấn đề bị chuyển lòng vòng. Thu thập thông tin tối thiểu giúp chuyển đúng người, đúng ngưỡng."},"B4::Close the issue when a workaround is proposed":{correct:!1,why:"Workaround mới là biện pháp tạm, chưa chứng minh flow đã phục hồi hoặc nguyên nhân được kiểm soát. Đóng sớm làm mất theo dõi và issue có thể quay lại."},"B4::Hide the blocker to protect status":{correct:!1,why:"Che blocker làm báo cáo đẹp giả tạo và tước cơ hội huy động hỗ trợ hoặc điều chỉnh cam kết. Khi mốc trễ lộ ra, chi phí phục hồi và mất niềm tin tăng."},"B5::Execute the planned response, manage the realized event as an issue, and communicate impact":{correct:!0,why:"Khi trigger xảy ra, rủi ro đã thành sự kiện thực tế cần quản như issue; phương án ứng phó đã chuẩn bị nên được kích hoạt và tác động phải minh bạch. Không thể tiếp tục chỉ theo dõi một rủi ro đã xảy ra.",exp:"Xác nhận trigger, kích hoạt phương án ứng phó có owner và ghi phần phát sinh thành issue. Đánh giá tác động, thông báo stakeholder và cập nhật dự phòng cùng kế hoạch. Bẫy là tiếp tục coi event là risk hoặc chỉ báo cáo variance sau khi thiệt hại xảy ra."},"B5::Analyze probability and impact, assign ownership, and plan a proportionate response":{correct:!0,why:"Đánh giá xác suất và tác động giúp phân biệt rủi ro cần xử lý với rủi ro chỉ theo dõi. Owner và phương án ứng phó tương xứng giúp dùng nguồn lực đúng mức, không phản ứng quá mạnh hoặc bỏ mặc.",exp:"Xác định mức phơi nhiễm, người có khả năng quản và biện pháp phù hợp. Ghi trigger, hạn, ngân sách và rà soát hiệu lực trong các kỳ tiếp theo. Bẫy là giao mọi risk cho PM hoặc dùng một response cho threat và opportunity."},"B5::Reassess residual and emerging risks and update responses and reserves":{correct:!0,why:"Sau phương án ứng phó, rủi ro còn lại và rủi ro mới có thể khác ban đầu. Đánh giá lại và cập nhật phương án ứng phó hoặc reserve tránh ảo tưởng rằng mọi nguy cơ đã biến mất.",exp:"Kiểm tra kết quả của phương án ứng phó và bối cảnh mới, tìm rủi ro thứ cấp. Cập nhật xác suất, tác động, owner và dự phòng rồi truyền đạt. Bẫy là xóa high risk hoặc coi risk planning kết thúc sau lần đầu."},"B5::Close the risk when its trigger occurs":{correct:!1,why:"Trigger thường là lúc kích hoạt phương án ứng phó hoặc chuyển rủi ro thành issue, không phải lúc đóng hồ sơ. Đóng ngay bỏ qua tác động và phần rủi ro dư sau sự kiện."},"B5::Wait for variance before responding":{correct:!1,why:"Chờ variance xuất hiện bỏ qua dấu hiệu sớm cho phép phòng ngừa. Khi sai lệch đo được, chi phí và thời gian phục hồi có thể đã tăng."},"B5::Assign every risk to the project manager":{correct:!1,why:"Tập trung mọi owner ở quản lý dự án làm giảm trách nhiệm của người kiểm soát nguyên nhân và tạo nút thắt. Rủi ro cần owner phù hợp với quyền hạn và biện pháp."},"B5::Use the same response for threats and opportunities":{correct:!1,why:"Threat cần giảm xác suất hoặc tác động, còn opportunity có thể cần khai thác hoặc tăng khả năng xảy ra. Dùng cùng phương án ứng phó bỏ qua bản chất và có thể xử lý sai cả hai."},"B5::Remove high risks from the register to improve status":{correct:!1,why:"Xóa rủi ro lớn chỉ làm trạng thái đẹp hơn, không làm phơi nhiễm giảm. Mất hồ sơ khiến owner và người quyết định không còn thấy nguy cơ."},"B5::Treat risk management as a one-time planning exercise":{correct:!1,why:"Rủi ro thay đổi theo tiến độ, giả định và môi trường nên phải được rà soát liên tục. Làm một lần bỏ qua trigger mới và phương án ứng phó không còn hiệu lực."},"B6::Turn the lesson into a measurable experiment and review the result":{correct:!0,why:"Bài học chỉ tạo cải tiến khi thành thay đổi có thể thử và có kết quả đo được. Thử nghiệm giới hạn rủi ro, còn review cho biết nên chuẩn hóa, điều chỉnh hay bỏ.",exp:"Xác định giả thuyết, thay đổi nhỏ, chỉ số và thời gian thử; giao owner. So sánh kết quả với đường cơ sở rồi quyết định bước tiếp theo. Bẫy là ghi lesson lặp lại hoặc tuyên bố thành công ngay khi giao việc."},"B6::Define the expected outcome, owner, measure, and review date for the improvement":{correct:!0,why:"Thiếu outcome, owner và ngày xem lại khiến cải tiến thành ý định không ai theo dõi. Bốn yếu tố biến đề xuất thành cam kết có thể đánh giá.",exp:"Viết rõ kết quả, người chịu trách nhiệm và cách đo trước triển khai. Đặt ngày review, thu thập dữ liệu và điều chỉnh hoặc dừng khi không đạt. Bẫy là không có measure hoặc review date, biến cải tiến thành ý định."},"B6::Standardize and share a proven improvement while monitoring context-specific effects":{correct:!0,why:"Cách làm đã chứng minh nên được chia sẻ để nhân rộng, nhưng bối cảnh các nhóm có thể khác nhau. Theo dõi tác động từng nơi tránh biến thực hành tốt ở một nhóm thành rủi ro ở nhóm khác.",exp:"Xác nhận bằng chứng đủ mạnh, cập nhật hướng dẫn và điều kiện áp dụng. Theo dõi chỉ số ở từng bối cảnh, rồi điều chỉnh khi tác động khác dự kiến. Bẫy là giữ practice trong một team hoặc áp dụng nơi khác mà không kiểm tra context."},"B6::Document the same lesson again":{correct:!1,why:"Chép lại bài học không thay đổi hành vi và chỉ làm tăng tài liệu. Bài học cần trở thành hành động hoặc thử nghiệm có owner để giảm vấn đề lặp lại."},"B6::Stop retrospectives because improvement was slow":{correct:!1,why:"Cải tiến chậm có thể cho thấy giả thuyết hoặc cách đo chưa đúng, không phải lý do loại bỏ nơi học tập. Dừng hồi tưởng làm mất cơ hội hiểu nguyên nhân."},"B6::Replace people before analyzing the process":{correct:!1,why:"Đổi người trước khi xem quy trình có thể đổ lỗi sai và giữ nguyên nguyên nhân hệ thống. Phải phân tích dữ kiện và luồng công việc để biết cần đổi kỹ năng hay cách làm."},"B6::Adopt every suggestion without testing":{correct:!1,why:"Không phải đề xuất nào cũng phù hợp với mục tiêu, chi phí hoặc bối cảnh; áp dụng tất cả tạo rủi ro mới. Thử nghiệm và đo kết quả giúp phân biệt ý tưởng có ích."},"B6::Declare success when the action is assigned":{correct:!1,why:"Giao việc chỉ chứng minh có người nhận, không chứng minh outcome đã cải thiện. Tuyên bố thành công sớm khiến vấn đề tái diễn mà không có dữ liệu."},"B6::Keep proven practices inside one team":{correct:!1,why:"Giữ thực hành đã chứng minh trong một nhóm làm tổ chức mất cơ hội nhân rộng và lặp lại chi phí học hỏi. Chia sẻ có điều kiện cho nhóm khác áp dụng và phản hồi."},"B7::Assess readiness and cultural, incentive, and workflow barriers before tailoring support":{correct:!0,why:"Việc dùng quy trình cũ có thể do kỹ năng, văn hóa, động lực hoặc workflow chứ không chỉ thiếu đào tạo. Đánh giá readiness và rào cản trước giúp hỗ trợ đúng nguyên nhân.",exp:"Xem năng lực, động lực, quy trình và ảnh hưởng của người dẫn dắt; xác định khoảng cách readiness. Chọn đào tạo, hỗ trợ hoặc thay đổi workflow phù hợp rồi đo adoption. Bẫy là lặp training hoặc tắt hệ thống cũ khi readiness chưa đủ."},"B7::Engage affected groups, build change champions, and address adoption feedback":{correct:!0,why:"Nhóm bị ảnh hưởng cần tham gia để hiểu lợi ích, nêu trở ngại và giúp điều chỉnh cách chuyển đổi. Change champion lan tỏa hành vi mới, còn phản hồi cho biết hỗ trợ nào còn thiếu.",exp:"Xác định nhóm ảnh hưởng và người có uy tín, mời họ đồng thiết kế cách áp dụng. Thu thập phản hồi sau triển khai và xử lý rào cản lặp lại. Bẫy là gắn nhãn người dùng chống đối mà bỏ qua informal leaders và feedback."},"B7::Track behavior and outcome adoption rather than training attendance alone":{correct:!0,why:"Tham dự đào tạo chỉ đo hoạt động, không chứng minh người dùng đổi hành vi hoặc tạo kết quả. Theo dõi sử dụng thực tế và outcome cho biết chuyển đổi có bền vững hay không.",exp:"Xác định hành vi và kết quả mong đợi, thu thập dữ liệu sử dụng cùng đường cơ sở. Tìm nhóm chưa áp dụng và điều chỉnh hỗ trợ dựa trên bằng chứng. Bẫy là dùng attendance hoặc deployment làm bằng chứng adoption."},"B7::Repeat the same training without diagnosis":{correct:!1,why:"Lặp nguyên khóa khi chưa biết rào cản là kỹ năng, động lực hay quy trình sẽ không đổi hành vi. Cần tìm nguyên nhân rồi thiết kế hỗ trợ phù hợp."},"B7::Disable the old system immediately regardless of readiness":{correct:!1,why:"Tắt hệ thống cũ khi người dùng chưa sẵn sàng có thể gián đoạn công việc và tạo phản ứng chống đối. Chuyển đổi cần điều kiện readiness, hỗ trợ và kế hoạch quay lui."},"B7::Label users as resistant and close the project":{correct:!1,why:"Gắn nhãn người dùng đổ lỗi cho cá nhân và bỏ qua nguyên nhân thiết kế, động lực hoặc quy trình. Đóng dự án khi adoption chưa đạt làm lợi ích thất bại."},"B7::Measure only deployment completion":{correct:!1,why:"Triển khai xong chỉ chứng minh hệ thống đã phát hành, không chứng minh người dùng áp dụng và lợi ích xuất hiện. Chỉ số này có thể xanh trong khi hành vi vẫn cũ."},"B7::Ask the sponsor to mandate enthusiasm":{correct:!1,why:"Mệnh lệnh có thể tạo tuân thủ ngắn hạn nhưng không giải quyết năng lực, workflow hay lý do cần thay đổi. Ép thể hiện nhiệt tình còn làm mất phản hồi trung thực."},"B7::Ignore informal leaders who influence behavior":{correct:!1,why:"Người dẫn dắt không chính thức ảnh hưởng lớn đến hành vi dù không có chức danh. Bỏ qua họ khiến thông điệp chính thức không lan tới công việc hằng ngày và có thể tạo mạng lưới phản đối."},"B8::Assess the external change with stakeholders and adapt the business case and priorities":{correct:!0,why:"Thay đổi bên ngoài có thể làm giả định doanh thu, nhu cầu hoặc lợi thế không còn đúng. Đánh giá cùng stakeholder rồi điều chỉnh business case và ưu tiên giúp bảo vệ giá trị thay vì trung thành với giả định cũ.",exp:"Xác minh thông tin, lượng hóa tác động lên lợi ích và rủi ro rồi hỏi các bên về lựa chọn. Cập nhật business case hoặc ưu tiên theo quản trị và theo dõi giả định mới. Bẫy là tiếp tục unchanged để bảo vệ baseline hoặc sao chép đối thủ ngay."},"B8::Evaluate impact on value, risk, scope, and supply before selecting a response":{correct:!0,why:"Một thay đổi có thể đồng thời ảnh hưởng giá trị, rủi ro, phạm vi và chuỗi cung ứng; phản ứng một chiều dễ tạo hậu quả ẩn. Đánh giá đủ các chiều giúp chọn phương án có lợi ích ròng và khả năng thực hiện.",exp:"Phân tích từng lựa chọn theo lợi ích, rủi ro, phạm vi, nguồn cung và thời gian. Trình bày đánh đổi, chọn phương án ứng phó được duyệt và cập nhật kế hoạch. Bẫy là đổi scope hoặc hủy dự án trước khi phân tích impact và governance."},"B8::Update assumptions and route strategic decisions through governance":{correct:!0,why:"Khi bằng chứng mới làm giả định cũ yếu đi, assumption log và quyết định chiến lược phải được cập nhật qua đúng cơ quan. Điều này giữ business case sống động, có dấu vết và có người chịu trách nhiệm.",exp:"Ghi giả định bị bác bỏ, dữ liệu thay thế và tác động; chuẩn bị các lựa chọn. Trình governance quyết định rồi cập nhật business case, kế hoạch và truyền thông. Bẫy là coi business case bất biến hoặc chờ tới annual planning."},"B8::Continue unchanged to protect the baseline":{correct:!1,why:"Giữ đường cơ sở không bảo vệ giá trị nếu giả định doanh thu hoặc nhu cầu đã đổi. Tiếp tục đầu tư có thể giao đúng phạm vi nhưng không còn lý do kinh doanh."},"B8::Copy the competitor immediately":{correct:!1,why:"Bắt chước ngay chưa cho biết khách hàng, năng lực hoặc chiến lược dự án có phù hợp hay không. Nó có thể tạo scope và chi phí mới mà không chứng minh lợi ích."},"B8::Cancel the project without governance review":{correct:!1,why:"Hủy dự án là quyết định chiến lược về đầu tư và lợi ích, không thể thực hiện chỉ để phản ứng với một tin bên ngoài. Bỏ quản trị làm mất phân tích lựa chọn và quyền phê duyệt."},"B8::Ignore external information until annual planning":{correct:!1,why:"Chờ chu kỳ hàng năm có thể để rủi ro hoặc cơ hội ảnh hưởng nhiều tháng trong khi quyết định còn điều chỉnh được. Thông tin đáng tin cần được đánh giá theo ngưỡng, không theo lịch cố định."},"B8::Change scope before impact analysis":{correct:!1,why:"Đổi phạm vi trước khi hiểu tác động có thể phá phụ thuộc, lịch, ngân sách và nguồn cung. Cần phân tích lựa chọn rồi xin quyết định có căn cứ."},"B8::Treat the business case as fixed after approval":{correct:!1,why:"Phê duyệt không bảo đảm giả định sẽ mãi đúng. Coi business case bất biến khiến dự án tiếp tục theo lợi ích đã mất và bỏ qua cơ hội tái định hướng."}},C={...q,...x,...R},u=["digital banking modernization","hospital scheduling platform","regional transit upgrade","retail analytics rollout","manufacturing automation initiative","public-sector portal","telecom network expansion","insurance claims transformation","renewable-energy program","university learning platform","pharmaceutical compliance project","logistics optimization product","cybersecurity improvement initiative","construction portfolio","customer-service AI product","global ERP rollout"],l=["What should the project manager do first?","What is the best next action for the project manager?","Which response best follows sound project management practice?","How should the project manager address this situation?"],p=["The sponsor needs a recommendation before the next governance review.","A decision is needed before the team makes an irreversible commitment.","The next release starts in two days and no additional budget is approved.","An external dependency will be locked at the end of the week.","The team can run one short experiment before committing to a solution.","The issue affects a benefit milestone due this quarter.","The proposed response must preserve auditability and clear ownership.","Several stakeholders are asking for action, but their priorities conflict.","The project manager has authority to facilitate but not to approve the final exception.","Current status data is incomplete and the steering meeting is tomorrow.","A similar situation caused avoidable rework in the previous increment.","The chosen action must work across two teams using different delivery cadences."],T=[{id:"P1",domain:"people",count:12,tag:"shared-vision",signals:["has three sponsors describing success in incompatible ways.","is about to start while business units disagree on the customer outcome.","has teams optimizing local targets without a shared product goal.","received a charter that different leaders interpret differently."],correct:["Facilitate alignment on one measurable vision and confirm shared understanding","Elicit each perspective, identify common value, and document an agreed vision","Use the charter and expected outcomes to build and validate a common vision"],wrong:["Ask the most senior sponsor to choose the vision alone","Let each team keep its own definition of success","Start delivery and resolve the disagreement after the first release","Convert every opinion directly into a separate requirement","Escalate the disagreement before facilitating a discussion","Measure team utilization instead of clarifying outcomes"],principle:"Tầm nhìn chung phải mô tả giá trị và được các bên cùng hiểu, không chỉ được một người có quyền lực chọn.",trap:"Bắt đầu giải pháp, chia nhỏ mục tiêu hoặc leo thang trước khi căn chỉnh sẽ làm tăng rework."},{id:"P2",domain:"people",count:12,tag:"conflict",signals:["has two specialists whose disagreement is stopping design decisions.","has a product owner and architect arguing publicly in every refinement.","has cultural tension that is reducing participation in workshops.","has team members defending positions without explaining their underlying interests."],correct:["Meet the parties, understand the source of conflict, and facilitate a collaborative resolution","Reinforce agreed ground rules and help the parties focus on interests rather than positions","Create a safe conversation, listen to each perspective, and agree on a workable resolution"],wrong:["Escalate immediately to both functional managers","Remove one party before investigating the conflict","Ignore the tension because technical results matter more","Vote on which person is right","Force a compromise without hearing the underlying interests","Cancel collaboration meetings until the conflict disappears"],principle:"Xung đột nên được hiểu từ nguồn gốc và lợi ích thật, rồi xử lý trực tiếp bằng hợp tác và ground rules.",trap:"Ép buộc, né tránh, thay người hoặc leo thang quá sớm không giải quyết nguyên nhân."},{id:"P3",domain:"people",count:12,tag:"leadership",signals:["has a capable team waiting for approval on every minor decision.","has a new team that needs direction but is receiving no coaching.","has declining motivation after repeated top-down assignments.","has unclear decision boundaries between the team and project manager."],correct:["Assess team maturity, clarify decision boundaries, and adapt the leadership style","Coach the team and delegate decisions at the level they are prepared to own","Use servant leadership to remove constraints while keeping accountability clear"],wrong:["Approve every decision personally to retain control","Delegate governance decisions without any boundaries","Replace the team lead immediately","Set higher utilization targets to improve motivation","Assign all decisions to the most senior technical expert","Avoid feedback so the team can self-organize"],principle:"Lãnh đạo hiệu quả thích ứng theo độ trưởng thành, trao quyền có ranh giới và tạo điều kiện cho đội.",trap:"Micromanage hoặc buông toàn bộ trách nhiệm đều tạo bottleneck hay khoảng trống governance."},{id:"P4",domain:"people",count:11,tag:"stakeholder-engagement",signals:["has identified a regulator with high influence and limited project knowledge.","is losing support from an operations leader who was previously neutral.","has a community group affected by delivery but missing from the stakeholder register.","receives little feedback from a high-interest customer representative."],correct:["Analyze the stakeholder’s needs and tailor an engagement approach","Meet the stakeholder, listen to concerns, and update the engagement strategy","Assess influence, interest, and current engagement before selecting communication actions"],wrong:["Send the complete project repository without assessing needs","Ask the sponsor to handle all engagement","Wait until the stakeholder formally complains","Classify the stakeholder once and never revisit the assessment","Use the same weekly report for every stakeholder","Reduce contact to avoid additional requirements"],principle:"Engagement bắt đầu bằng nhận diện, phân tích nhu cầu và tương tác hai chiều được điều chỉnh theo phản hồi.",trap:"Gửi nhiều thông tin hoặc giao hết cho sponsor không thay thế việc hiểu stakeholder."},{id:"P5",domain:"people",count:11,tag:"expectation-alignment",signals:["has a sponsor expecting a global launch while the product owner expects a pilot.","has departments using different definitions of an acceptable release.","has a customer expecting features that are outside the approved objective.","has executives disagreeing about benefits and delivery timing."],correct:["Facilitate a discussion using approved objectives to align and document expectations","Make the expectation gap visible and obtain agreement on one achievable outcome","Clarify assumptions, constraints, and success criteria with the affected stakeholders"],wrong:["Use the expectation of the most senior stakeholder","Let both interpretations continue until acceptance","Ask the team to build for every possible expectation","Treat a distributed document as proof of agreement","Promise the larger outcome before impact analysis","Postpone alignment until final delivery"],principle:"Kỳ vọng mâu thuẫn phải được làm rõ, so sánh với mục tiêu và chốt thành cam kết chung.",trap:"Im lặng, hứa quá mức hoặc mặc định quyền lực đồng nghĩa với đúng sẽ tạo thất vọng về sau."},{id:"P6",domain:"people",count:11,tag:"expectation-management",signals:["meets acceptance criteria while customer satisfaction declines each release.","has stakeholders surprised by outcomes despite receiving status reports.","shows increasing complaints even though scope and schedule remain green.","has users reporting that delivered increments no longer solve their priority problem."],correct:["Investigate the expectation gap with stakeholders and adapt outcomes or engagement","Use feedback and satisfaction measures to identify what must change","Review evolving needs with customers and confirm adjusted expectations continuously"],wrong:["Report success because the baseline is green","Increase delivery velocity without customer discussion","Tighten internal reporting and ignore external feedback","Wait for final acceptance to measure satisfaction","Add more features without identifying the gap","Tell customers their expectations cannot evolve"],principle:"Quản lý kỳ vọng là theo dõi liên tục mức hài lòng và điều chỉnh khi nhu cầu hoặc giá trị cảm nhận thay đổi.",trap:"Đúng scope hay nhanh hơn không chứng minh outcome còn có giá trị với khách hàng."},{id:"P7",domain:"people",count:11,tag:"knowledge-transfer",signals:["will lose a specialist who owns a critical procedure in two weeks.","has important operational knowledge held by one contractor.","is transitioning support to a team that has only read the documentation.","repeatedly relearns the same lesson when team members rotate."],correct:["Pair knowledge holders with successors, practise the work, and verify capability","Plan hands-on transfer, capture gaps, and store reusable knowledge","Identify critical knowledge early and validate that recipients can apply it"],wrong:["Ask the specialist to upload existing files only","Wait until the expert leaves before hiring a replacement","Record knowledge loss as a risk without transfer actions","Schedule one lecture with no practice","Store documents in a private folder owned by the departing expert","Assume experienced staff will learn the procedure independently"],principle:"Chuyển giao chỉ hoàn tất khi người nhận có thể áp dụng tri thức, không phải khi file đã được tải lên.",trap:"Tài liệu thụ động, bàn giao muộn hoặc không kiểm chứng đều để lại single point of failure."},{id:"P8",domain:"people",count:11,tag:"communication",signals:["has executives needing monthly forecasts and a team needing daily blocker visibility.","has remote teams misunderstanding decisions made in live meetings.","has a stakeholder saying reports are detailed but not useful.","has sensitive risk information requiring different audiences and channels."],correct:["Tailor content, channel, cadence, and feedback to each audience","Update the communication approach based on stakeholder information needs","Confirm understanding through two-way communication rather than transmission alone"],wrong:["Send one detailed daily report to everyone","Copy all stakeholders on every message","Communicate only with high-power stakeholders","Replace conversations with a shared folder","Increase report length without asking what decisions it supports","Assume silence means the message was understood"],principle:"Giao tiếp hiệu quả phù hợp người nhận, quyết định cần hỗ trợ, kênh, nhịp và vòng phản hồi.",trap:"Một mẫu cho mọi người hoặc chỉ tăng lượng thông tin thường làm tín hiệu quan trọng khó thấy hơn."},{id:"R1",domain:"process",count:12,tag:"integrated-plan",signals:["has stable hardware requirements and software that needs frequent feedback.","combines regulated milestones with uncertain customer-facing features.","has workstreams using incompatible plans and dependency assumptions.","must choose a lifecycle before detailed planning begins."],correct:["Assess uncertainty and dependencies, tailor the lifecycle, and integrate the plans","Use a hybrid approach where stable work is planned predictively and uncertain work iteratively","Create an integrated plan that connects governance, delivery, dependencies, and change"],wrong:["Use predictive delivery for every workstream","Use agile delivery for every workstream regardless of constraints","Allow each team to plan independently with no integration","Delay lifecycle selection until execution is complete","Copy the plan from a previous project","Focus only on schedule and omit governance and benefits"],principle:"Kế hoạch tích hợp nối approach, phụ thuộc, governance và delivery; lifecycle phải được tailor theo độ bất định.",trap:"Áp một phương pháp cho mọi phần hoặc để kế hoạch tách rời sẽ che mất dependency."},{id:"R2",domain:"process",count:12,tag:"scope",signals:["has approved high-level scope but deliverables are not manageable.","receives an attractive feature request outside the current baseline.","has backlog items with conflicting acceptance boundaries.","has stakeholders disagreeing about what is explicitly out of scope."],correct:["Clarify requirements and boundaries, then decompose work into manageable components","Assess the request against scope and use the agreed change or backlog process","Validate scope understanding and acceptance criteria with relevant stakeholders"],wrong:["Start the easiest work before defining boundaries","Accept every valuable-sounding request immediately","Freeze scope so no approved change is possible","Let developers infer missing acceptance criteria","Use schedule variance to define product scope","Decompose work before understanding the deliverable"],principle:"Scope đi từ yêu cầu và ranh giới được đồng thuận tới WBS hoặc backlog có thể quản lý và xác nhận.",trap:"Làm trước khi rõ ranh giới hoặc nhận thay đổi không qua quy trình sẽ tạo scope creep."},{id:"R3",domain:"process",count:12,tag:"value-delivery",signals:["must choose between a popular feature and a compliance enabler that unlocks revenue.","delivers many features while measured benefits remain flat.","has a backlog ordered by requester seniority rather than outcomes.","can release a small usable increment before the full solution."],correct:["Prioritize by value, risk, dependencies, and time to benefit","Deliver a usable value slice early and measure the outcome","Revisit priorities with stakeholders using benefit evidence and feedback"],wrong:["Prioritize the item with the largest effort estimate","Choose only the most popular request","Maximize the number of completed features","Order work by stakeholder title","Delay all value until the complete solution is finished","Treat velocity as the business benefit"],principle:"Value-based delivery ưu tiên outcome, dependency và thời gian mở khóa lợi ích, rồi đo benefit thực tế.",trap:"Nhiều output, story point hoặc yêu cầu của người quyền lực không tự động tạo giá trị."},{id:"R4",domain:"process",count:11,tag:"resources",signals:["lacks a critical security skill for the next two iterations.","has two specialists allocated at 150 percent across projects.","faces equipment constraints that threaten a planned work package.","has a new team whose capability differs from the staffing assumption."],correct:["Assess the capability and availability gap, then collaborate on a feasible resource response","Balance demand with capacity using training, pairing, sequencing, or approved support","Update the resource plan and commitments based on realistic availability"],wrong:["Commit the work and expect overtime","Remove quality criteria that require the missing skill","Assume all resources with the same title are interchangeable","Add people without considering onboarding cost","Hide the shortage until a milestone is missed","Allocate the same specialist full-time to multiple projects"],principle:"Nguồn lực gồm số lượng, kỹ năng và thời điểm sẵn có; cam kết phải dựa trên capacity thực.",trap:"Overtime, thêm người mù quáng hoặc hạ chất lượng chỉ chuyển vấn đề sang nơi khác."},{id:"R5",domain:"process",count:11,tag:"procurement",signals:["has clear scope and wants the seller to carry cost-overrun risk.","needs specialist support while the exact volume of work is uncertain.","has a supplier missing service levels for the third month.","must decide whether to build a capability internally or purchase it."],correct:["Match the procurement and contract strategy to scope certainty and risk allocation","Use objective criteria to evaluate options and follow the approved source-selection process","Review contract obligations and performance, then apply the agreed corrective process"],wrong:["Always choose the lowest bid","Use a verbal agreement to save time","Select fixed price when scope is highly uncertain without safeguards","Change supplier obligations outside the contract","Ignore make-or-buy analysis","Accept repeated misses to preserve the relationship"],principle:"Procurement phải nối nhu cầu, make-or-buy, loại hợp đồng, phân bổ rủi ro và quản lý hiệu suất.",trap:"Giá thấp nhất hoặc loại hợp đồng quen thuộc chưa chắc phù hợp độ rõ scope và risk."},{id:"R6",domain:"process",count:11,tag:"finance",signals:["has an identified risk occur and needs funds for the approved response.","shows actual cost variance but incomplete progress data.","needs a budget for uncertain work and known risks.","receives a forecast that no longer matches current performance."],correct:["Use the appropriate approved reserve and maintain transparent cost records","Validate progress and cost data before forecasting and choosing corrective action","Update the forecast using current evidence and follow financial governance"],wrong:["Use management reserve without approval for any overrun","Move costs to operations to protect the baseline","Hide variance until the next funding cycle","Treat spent budget as equivalent to earned progress","Remove contingency to improve the forecast","Approve funding beyond the project manager’s authority"],principle:"Quản lý tài chính phân biệt baseline, contingency, management reserve, actuals và forecast theo governance.",trap:"Che variance, dùng sai reserve hoặc quyết định vượt quyền làm mất minh bạch tài chính."},{id:"R7",domain:"process",count:11,tag:"quality",signals:["finds defects only during sprint review.","has acceptance criteria interpreted differently by developers and testers.","passes inspection but repeatedly fails in customer use.","has a recurring defect despite several corrections."],correct:["Analyze the cause and build quality checks earlier into the workflow","Clarify measurable acceptance criteria and agree how evidence will be produced","Use root-cause analysis and implement a preventive process improvement"],wrong:["Add only more inspection at the end","Accept defects when delivery velocity is high","Reduce customer reviews to avoid finding issues","Correct each defect without examining recurrence","Make quality the tester’s responsibility alone","Lower the acceptance threshold after work is complete"],principle:"Quality ưu tiên prevention, tiêu chí đo được, kiểm tra sớm và RCA thay vì chỉ bắt lỗi cuối quy trình.",trap:"Inspection cuối, hạ chuẩn hoặc giao chất lượng cho một vai trò không ngăn lỗi tái diễn."},{id:"R8",domain:"process",count:11,tag:"schedule",signals:["has a critical-path regulatory review likely to finish late.","has a milestone slipping because a predecessor estimate was optimistic.","has parallel work competing for the same constrained specialist.","receives a request to compress the schedule without changing scope."],correct:["Assess dependencies and schedule impact before selecting a response","Update the schedule with realistic estimates and evaluate response options","Analyze critical path, resource constraints, cost, and risk before compression"],wrong:["Crash all downstream work immediately","Hide the delay until it becomes certain","Remove a mandatory milestone","Add resources to every activity","Shorten estimates without team input","Report percent complete without dependency analysis"],principle:"Schedule management đọc dependency, critical path, resource và risk trước khi chọn fast tracking hay crashing.",trap:"Nén lịch theo phản xạ hoặc chỉnh số liệu không giải quyết nguyên nhân và có thể tăng rủi ro."},{id:"R9",domain:"process",count:11,tag:"project-status",signals:["shows higher velocity alongside more escaped defects.","has a green schedule but declining benefit realization.","uses percent complete that conflicts with earned-value evidence.","has executives requesting one health indicator for a complex program."],correct:["Use balanced delivery, quality, risk, and outcome measures to explain true status","Validate data and present trends, variances, implications, and decisions needed","Tailor status artifacts while preserving transparent evidence and context"],wrong:["Report green using the most favorable metric","Stop reporting any metric that creates concern","Present raw data without interpretation","Use velocity as a cross-team productivity target","Delay bad news until a recovery plan is certain","Replace evidence with subjective confidence"],principle:"Status phải phản ánh nhiều chiều, xu hướng và quyết định cần hỗ trợ thay vì tối ưu một con số đẹp.",trap:"Cherry-pick metric hoặc giấu tin xấu làm governance ra quyết định trên tín hiệu sai."},{id:"R10",domain:"process",count:11,tag:"closure",signals:["has customer acceptance but operations training remains incomplete.","has a canceled project with contracts and records still open.","has delivered the product but has not confirmed benefit ownership.","is releasing team members before lessons and administrative closure are captured."],correct:["Verify transition readiness and complete agreed closure activities","Close contracts, archive records, capture lessons, and obtain formal acceptance as applicable","Confirm operational ownership, open actions, and benefit-transition responsibilities"],wrong:["Close as soon as development stops","Transfer unresolved actions informally and release everyone","Skip lessons because the project was canceled","Keep contracts open after final payment","Assume product acceptance proves operational readiness","Delete project records to reduce storage"],principle:"Closure gồm acceptance, transition, contracts, records, lessons và ownership sau dự án.",trap:"Dừng delivery không đồng nghĩa dự án đã đóng hoặc vận hành đã sẵn sàng."},{id:"B1",domain:"business",count:9,tag:"governance",signals:["has a requested change exceeding the project manager’s cost authority.","has teams unclear about who approves risk acceptance.","has a steering committee receiving decisions with no thresholds.","has governance designed for a small project but now operating at program scale."],correct:["Follow defined decision rights and escalate through the appropriate governance path","Clarify roles, thresholds, evidence, and escalation before the next decision","Tailor governance to complexity while preserving accountability and transparency"],wrong:["Approve the decision because delay is inconvenient","Reject every request above the threshold","Let the loudest stakeholder decide","Create an unofficial path around the steering committee","Escalate every minor operational choice","Treat governance as status reporting only"],principle:"Governance xác định quyền quyết định, ngưỡng, bằng chứng và escalation tương xứng với bối cảnh.",trap:"Vượt quyền hoặc đẩy mọi việc lên trên đều làm chậm và giảm accountability."},{id:"B2",domain:"business",count:9,tag:"compliance",signals:["faces a privacy rule effective before the next release.","discovers required safety evidence is missing before deployment.","has teams interpreting a new regulation differently.","must prove continuing compliance after controls are implemented."],correct:["Confirm the obligation with qualified experts and assess impact before acting","Define required evidence, ownership, and verification in the delivery plan","Monitor controls and remediate gaps through the appropriate governance process"],wrong:["Release first and fix compliance later","Let each developer interpret the regulation independently","Remove functionality without impact analysis","Treat compliance as a one-time final audit","Hide the gap to protect the launch date","Ask the customer to accept legal risk informally"],principle:"Compliance cần xác nhận nghĩa vụ, đánh giá impact, tạo bằng chứng và giám sát liên tục.",trap:"Đoán luật, trì hoãn tới cuối hoặc đánh đổi compliance lấy deadline có thể làm dự án không được phép vận hành."},{id:"B3",domain:"business",count:9,tag:"change-control",signals:["has an executive requesting development before formal approval.","receives a baseline change with unknown schedule and benefit impact.","has an agile team accepting stakeholder requests outside product-owner prioritization.","has an approved change not reflected in plans or communications."],correct:["Record the request, assess impact, and route it through the agreed decision process","Implement only after authorization, then update affected plans and communicate","Use the tailored change or backlog process while preserving traceability"],wrong:["Start work because the requester is senior","Reject all changes because the baseline is fixed","Ask the team to work unofficially","Approve before impact analysis","Update only the schedule after approval","Let every stakeholder reprioritize the backlog directly"],principle:"Change đi theo request, impact, approval, implementation, update và communication với traceability.",trap:"Shadow work hoặc phê duyệt không phân tích phá baseline và làm mất dấu quyết định."},{id:"B4",domain:"business",count:9,tag:"impediments-issues",signals:["has a test environment outage blocking the team today.","has an unresolved dependency that has become an active issue.","has multiple impediments competing for limited escalation capacity.","has a recurring blocker whose owner and due date are unclear."],correct:["Make the issue visible, assess impact, assign ownership, and coordinate removal","Prioritize active impediments by impact and urgency, then track resolution","Address the root constraint and confirm that flow has actually resumed"],wrong:["Record the active outage only as a future risk","Wait for the retrospective to act","Increase commitment while the team is blocked","Escalate without first identifying ownership and impact","Close the issue when a workaround is proposed","Hide the blocker to protect status"],principle:"Issue đã xảy ra cần visibility, priority, owner, action và xác nhận đã gỡ; risk tương lai được quản khác.",trap:"Chờ đợi, tăng tải hoặc chỉ đổi nhãn không khôi phục flow."},{id:"B5",domain:"business",count:9,tag:"risk",signals:["has a documented supplier-delay trigger occur.","identifies a high-impact uncertainty with no owner.","has residual risk after an approved response.","finds risk assumptions changed after new market information."],correct:["Execute the planned response, manage the realized event as an issue, and communicate impact","Analyze probability and impact, assign ownership, and plan a proportionate response","Reassess residual and emerging risks and update responses and reserves"],wrong:["Close the risk when its trigger occurs","Wait for variance before responding","Assign every risk to the project manager","Use the same response for threats and opportunities","Remove high risks from the register to improve status","Treat risk management as a one-time planning exercise"],principle:"Risk management nối nhận diện, phân tích, owner, response, trigger và giám sát; sự kiện đã xảy ra chuyển sang issue.",trap:"Risk register không phải nơi cất danh sách rồi chờ variance xuất hiện."},{id:"B6",domain:"business",count:9,tag:"continuous-improvement",signals:["has identified the same review bottleneck in three retrospectives.","has a lesson recorded but no behavior or metric changed.","runs an improvement experiment with unclear success criteria.","finds one team’s successful practice could benefit other teams."],correct:["Turn the lesson into a measurable experiment and review the result","Define the expected outcome, owner, measure, and review date for the improvement","Standardize and share a proven improvement while monitoring context-specific effects"],wrong:["Document the same lesson again","Stop retrospectives because improvement was slow","Replace people before analyzing the process","Adopt every suggestion without testing","Declare success when the action is assigned","Keep proven practices inside one team"],principle:"Continuous improvement biến insight thành thử nghiệm đo được, học từ kết quả rồi chuẩn hóa hoặc điều chỉnh.",trap:"Ghi lesson mà không thay đổi hành vi và metric không tạo cải tiến."},{id:"B7",domain:"business",count:8,tag:"organizational-change",signals:["has trained users who continue using the legacy workflow.","faces middle managers resisting a new operating model.","has adoption metrics below target despite technical readiness.","introduces a change that conflicts with existing incentives and culture."],correct:["Assess readiness and cultural, incentive, and workflow barriers before tailoring support","Engage affected groups, build change champions, and address adoption feedback","Track behavior and outcome adoption rather than training attendance alone"],wrong:["Repeat the same training without diagnosis","Disable the old system immediately regardless of readiness","Label users as resistant and close the project","Measure only deployment completion","Ask the sponsor to mandate enthusiasm","Ignore informal leaders who influence behavior"],principle:"Organizational change cần readiness, participation, incentives, support và đo adoption thực.",trap:"Training attendance hoặc technical go-live không chứng minh hành vi đã thay đổi."},{id:"B8",domain:"business",count:8,tag:"external-environment",signals:["sees a competitor invalidate a key revenue assumption.","faces a geopolitical event affecting a critical supplier.","learns that a new technology changes the product’s value proposition.","has an economic shift alter demand and benefit forecasts."],correct:["Assess the external change with stakeholders and adapt the business case and priorities","Evaluate impact on value, risk, scope, and supply before selecting a response","Update assumptions and route strategic decisions through governance"],wrong:["Continue unchanged to protect the baseline","Copy the competitor immediately","Cancel the project without governance review","Ignore external information until annual planning","Change scope before impact analysis","Treat the business case as fixed after approval"],principle:"Thay đổi bên ngoài phải được quét, đánh giá lên business case và phản ánh vào priority hoặc plan qua governance.",trap:"Bám baseline mù quáng hay phản ứng cực đoan đều bỏ qua value và impact."}],c={predictive:114,agile:79,hybrid:81},e={predictive:0,agile:0,hybrid:0},B=()=>{const n=e.predictive<c.predictive?e.predictive/c.predictive:Number.POSITIVE_INFINITY,t=e.agile<c.agile?e.agile/c.agile:Number.POSITIVE_INFINITY,h=e.hybrid<c.hybrid?e.hybrid/c.hybrid:Number.POSITIVE_INFINITY;return n<=t&&n<=h?"predictive":t<=h?"agile":"hybrid"},m=[];let a=227;const d=(n,t)=>{const h=`${n.id}::${t}`,i=C[h];if(!i)throw new Error(`Missing option rationale: ${h}`);return i},P=({task:n,option:t,correct:h})=>{const i=d(n,t);if(i.correct!==h)throw new Error(`Incorrect rationale flag: ${n.id}::${t}`);return i.why},A=({task:n,option:t})=>{const h=d(n,t);if(!h.correct||!h.exp)throw new Error(`Missing correct explanation: ${n.id}::${t}`);return h.exp};for(const n of T)for(let t=0;t<n.count;t++,a++){const h=B();h==="predictive"?e.predictive++:h==="agile"?e.agile++:e.hybrid++;const i=u[(a+t*3)%u.length],v=n.signals[t%n.signals.length],y=p[t%p.length],k=l[(a+t)%l.length],g=n.correct[t%n.correct.length],b=[0,1,2].map(s=>n.wrong[(t*2+s)%n.wrong.length]),o=a%4,r=[...b];r.splice(o,0,g);const f=r.map((s,w)=>P({task:n,option:s,correct:w===o}));m.push({id:`o${a}`,n:a,t:0,origin:"original",eco:n.id,domain:n.domain,approach:h,tags:[n.tag,h,"eco-2026"],type:"mc",q:`A ${h} ${i} ${v} ${y} ${k}`,opts:r,ans:[o],why:f,exp:A({task:n,option:g})})}const j=m;export{S as O,j as a};
